(9074, 501, '_full_width_components_2_alternating_image_text_2_image', 'field_5e70f0ef0dfd6'),
(9075, 501, 'full_width_components_2_alternating_image_text', '3'),
(9076, 501, '_full_width_components_2_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(9077, 501, 'full_width_components_3_text', 'Immersive Learning'),
(9078, 501, '_full_width_components_3_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(9079, 501, 'full_width_components_3_background_image', '499'),
(9080, 501, '_full_width_components_3_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(9081, 501, 'full_width_components_4_component_title', 'Tomorrow’s Training Today'),
(9082, 501, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(9083, 501, 'full_width_components_4_component_subtitle', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(9084, 501, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(9085, 501, 'full_width_components_4_content', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-full\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18.png\" alt=\"\" width=\"1819\" height=\"679\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean\r\n<blockquote>“Knowledge results from the combination of grasping experience and transforming it.”\r\n\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></blockquote>\r\nFind out more about immersive training and how <b>View360 Global™</b> can help you transform your business'),
(9086, 501, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
