(9351, 505, 'full_width_components_2_component_title', ''),
(9352, 505, '_full_width_components_2_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(9353, 505, 'full_width_components_2_alternating_image_text_0_title', 'Facilitation'),
(9354, 505, '_full_width_components_2_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(9355, 505, 'full_width_components_2_alternating_image_text_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(9356, 505, '_full_width_components_2_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(9357, 505, 'full_width_components_2_alternating_image_text_0_read_more_link', ''),
(9358, 505, '_full_width_components_2_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(9359, 505, 'full_width_components_2_alternating_image_text_0_image', '493'),
(9360, 505, '_full_width_components_2_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(9361, 505, 'full_width_components_2_alternating_image_text_1_title', 'The platform'),
(9362, 505, '_full_width_components_2_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(9363, 505, 'full_width_components_2_alternating_image_text_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve. '),
(9364, 505, '_full_width_components_2_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(9365, 505, 'full_width_components_2_alternating_image_text_1_read_more_link', ''),
(9366, 505, '_full_width_components_2_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(9367, 505, 'full_width_components_2_alternating_image_text_1_image', '496'),
(9368, 505, '_full_width_components_2_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(9369, 505, 'full_width_components_2_alternating_image_text_2_title', 'virtual conferencing'),
(9370, 505, '_full_width_components_2_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(9371, 505, 'full_width_components_2_alternating_image_text_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(9372, 505, '_full_width_components_2_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(9373, 505, 'full_width_components_2_alternating_image_text_2_read_more_link', ''),
(9374, 505, '_full_width_components_2_alternating_image_text_2_read_more_link', 'field_5eac06535f1f3'),
(9375, 505, 'full_width_components_2_alternating_image_text_2_image', '497'),
(9376, 505, '_full_width_components_2_alternating_image_text_2_image', 'field_5e70f0ef0dfd6'),
(9377, 505, 'full_width_components_2_alternating_image_text', '3'),
(9378, 505, '_full_width_components_2_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(9379, 505, 'full_width_components_3_text', 'Immersive Learning, Tomorrow’s Training Today'),
(9380, 505, '_full_width_components_3_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(9381, 505, 'full_width_components_3_background_image', '499'),
(9382, 505, '_full_width_components_3_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(9383, 505, 'full_width_components_4_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(9384, 505, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(9385, 505, 'full_width_components_4_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(9386, 505, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(9387, 505, 'full_width_components_4_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean\r\n\r\n<blockquote>“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></blockquote>\r\n\r\nFind out more about immersive training and how <b>View360 Global™</b> can help you transform your business'),
(9388, 505, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(9389, 505, 'full_width_components_4_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(9390, 505, '_full_width_components_4_buttons_0_button', 'field_5eabf7d5bf1a9'),
(9391, 505, 'full_width_components_4_buttons_1_button', 'a:3:{s:5:\"title\";s:20:\"BOOK A DEMONSTRATION\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(9392, 505, '_full_width_components_4_buttons_1_button', 'field_5eabf7d5bf1a9'),
(9393, 505, 'full_width_components_4_buttons', '2'),
(9394, 505, '_full_width_components_4_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(9395, 505, 'full_width_components_5_component_title', 'Immersive media - bringing creativity to life'),
(9396, 505, '_full_width_components_5_component_title', 'field_5e3bd2cd0eec0_field_5ea9847fcbc59'),
(9397, 505, 'full_width_components_5_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(9398, 505, '_full_width_components_5_component_subtitle', 'field_5e3bd2cd0eec0_field_5ea98490cbc5a'),
(9399, 505, 'full_width_components_5_icons_0_icon', '504'),
(9400, 505, '_full_width_components_5_icons_0_icon', 'field_5ea984ddcbc5d'),
(9401, 505, 'full_width_components_5_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(9402, 505, '_full_width_components_5_icons_0_text', 'field_5ea984e6cbc5e'),
(9403, 505, 'full_width_components_5_icons', '1'),
(9404, 505, '_full_width_components_5_icons', 'field_5e3bd2cd0eec0_field_5ea9849acbc5b'),
(9405, 505, 'full_width_components_5_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(9406, 505, '_full_width_components_5_component_bottom_content', 'field_5e3bd2cd0eec0_field_5ea984a5cbc5c'),
(9423, 506, 'page_title_override', 'View360 Global™ '),
