(9609, 509, 'components_0_content', '<p style=\"padding-left: 80px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n<p style=\"text-align: center;\"><b>Multilingual</b><b> Data Capture</b></p>'),
(9610, 509, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(9611, 509, 'full_width_components_0_component_title', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met . '),
(9612, 509, '_full_width_components_0_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(9613, 509, 'full_width_components_0_alternating_image_text_0_title', 'Providing Proof'),
(9614, 509, '_full_width_components_0_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(9615, 509, 'full_width_components_0_alternating_image_text_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(9616, 509, '_full_width_components_0_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(9617, 509, 'full_width_components_0_alternating_image_text_0_read_more_link', ''),
(9618, 509, '_full_width_components_0_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(9619, 509, 'full_width_components_0_alternating_image_text_0_image', '310'),
(9620, 509, '_full_width_components_0_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(9621, 509, 'full_width_components_0_alternating_image_text_1_title', 'Capturing learning activity'),
(9622, 509, '_full_width_components_0_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(9623, 509, 'full_width_components_0_alternating_image_text_1_text', 'View360 Global™ captures the  learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results. '),
(9624, 509, '_full_width_components_0_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(9625, 509, 'full_width_components_0_alternating_image_text_1_read_more_link', ''),
