(9629, 509, 'full_width_components_0_alternating_image_text', '2'),
(9630, 509, '_full_width_components_0_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(9631, 509, 'full_width_components_1_component_title', 'Measuring the impact of your learning'),
(9632, 509, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(9633, 509, 'full_width_components_1_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(9634, 509, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
