(11675, 564, '_full_width_components_0_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(11676, 564, 'full_width_components_0_component_subtitle', 'Training in The Isle of Man'),
(11677, 564, '_full_width_components_0_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(11678, 564, 'full_width_components_0_icons_0_icon', '523'),
(11679, 564, '_full_width_components_0_icons_0_icon', 'field_5ea984ddcbc5d'),
(11680, 564, 'full_width_components_0_icons_0_text', 'Headquarters <br>Isle of Man <br><br>  Website <br> https://www.expol.co.uk/'),
(11681, 564, '_full_width_components_0_icons_0_text', 'field_5ea984e6cbc5e'),
(11682, 564, 'full_width_components_0_icons', '1'),
(11683, 564, '_full_width_components_0_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(11684, 564, 'full_width_components_0_component_bottom_content', '<h1>The Challenge</h1>\r\nOur client provides regular training for various IOM Government Departments and the financial sector.\r\n\r\nTheir company was required to deliver a series of immersive critical incident response scenarios for the IOM Ship Registry, compliance training for the financial sector and a cybersecurity workshop for SME private sector companies'),
(11685, 564, '_full_width_components_0_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(11686, 564, 'full_width_components_1_component_title', ''),
(11687, 564, '_full_width_components_1_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(11688, 564, 'full_width_components_1_testimonials_0_text', ' “The use of View360 Global engendered genuine interest with our Clients, who were able to experience something quite unique in the classroom.  This software had never been seen before by anyone and proved an instant hit with the audience, who were totally engaged and eager to participate in the workshop.  At its conclusion, they left having enjoyed a thoroughly new method of learning.   Its flexible, adaptable and has the potential to revolutionise the training environment.  We highly recommend it.  We will definitely be working with this in the future”   '),
(11689, 564, '_full_width_components_1_testimonials_0_text', 'field_5cac5d7b5b816'),
(11690, 564, 'full_width_components_1_testimonials_0_author', 'Rob Kinrade CEO'),
(11691, 564, '_full_width_components_1_testimonials_0_author', 'field_5eac2ec641dad'),
(11692, 564, 'full_width_components_1_testimonials', '1'),
(11693, 564, '_full_width_components_1_testimonials', 'field_5eac2de411183_field_5cac59535b813'),
(11694, 564, 'full_width_components_1_button', ''),
(11695, 564, '_full_width_components_1_button', 'field_5eac2de411183_field_5eac2edad830e'),
(11696, 564, 'full_width_components_2_component_title', ''),
(11697, 564, '_full_width_components_2_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(11698, 564, 'full_width_components_2_alternating_image_text_0_title', 'How We Assisted'),
(11699, 564, '_full_width_components_2_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(11700, 564, 'full_width_components_2_alternating_image_text_0_text', 'Collaborating closely with EXPOL and their established clients, we co designed and delivered a series of independent and well attended blended learning training events, where the immersive scenarios and media content were specifically designed to meet the operational needs of the diverse beneficiary organisations'),
(11701, 564, '_full_width_components_2_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(11702, 564, 'full_width_components_2_alternating_image_text_0_read_more_link', ''),
(11703, 564, '_full_width_components_2_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(11704, 564, 'full_width_components_2_alternating_image_text_0_image', '465'),
(11705, 564, '_full_width_components_2_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(11706, 564, 'full_width_components_2_alternating_image_text_1_title', 'What was Achieved'),
(11707, 564, '_full_width_components_2_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(11708, 564, 'full_width_components_2_alternating_image_text_1_text', 'By delivering meaningful training using View360 Global for EXPOL’s clients we were able to provide them with a style of training that had not been experienced before by the participants. The consolidated experiential learning achieved and enjoyed by the participants evidenced value for money returned repeat business for EXPOL who continue to use the platform in their training programs'),
(11709, 564, '_full_width_components_2_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(11710, 564, 'full_width_components_2_alternating_image_text_1_read_more_link', ''),
