(11941, 566, '_full_width_components_5_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(11942, 566, 'full_width_components_6_text', 'Immersive Learning, Tomorrow’s Training Today'),
(11943, 566, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(11944, 566, 'full_width_components_6_text_position', 'right'),
(11945, 566, '_full_width_components_6_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(11946, 566, 'full_width_components_6_background_image', '499'),
(11947, 566, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(11948, 566, 'full_width_components_7_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(11949, 566, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(11950, 566, 'full_width_components_7_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(11951, 566, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(11952, 566, 'full_width_components_7_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(11953, 566, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(11954, 566, 'full_width_components_7_buttons_0_button', ''),
(11955, 566, '_full_width_components_7_buttons_0_button', 'field_5eabf7d5bf1a9'),
(11956, 566, 'full_width_components_7_buttons_1_button', ''),
(11957, 566, '_full_width_components_7_buttons_1_button', 'field_5eabf7d5bf1a9'),
(11958, 566, 'full_width_components_7_buttons', '2'),
(11959, 566, '_full_width_components_7_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(11960, 566, 'full_width_components_8_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(11961, 566, '_full_width_components_8_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(11962, 566, 'full_width_components_9_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(11963, 566, '_full_width_components_9_buttons_0_button', 'field_5ed90856b39bb'),
(11964, 566, 'full_width_components_9_buttons_1_button', 'a:3:{s:5:\"title\";s:20:\"Book a Demonstration\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(11965, 566, '_full_width_components_9_buttons_1_button', 'field_5ed90856b39bb'),
(11966, 566, 'full_width_components_9_buttons', '2'),
(11967, 566, '_full_width_components_9_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(11968, 566, 'full_width_components_10_component_title', 'Immersive media - bringing creativity to life'),
(11969, 566, '_full_width_components_10_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(11970, 566, 'full_width_components_10_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(11971, 566, '_full_width_components_10_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(11972, 566, 'full_width_components_10_icons_0_icon', '504'),
(11973, 566, '_full_width_components_10_icons_0_icon', 'field_5ea984ddcbc5d'),
(11974, 566, 'full_width_components_10_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(11975, 566, '_full_width_components_10_icons_0_text', 'field_5ea984e6cbc5e'),
(11976, 566, 'full_width_components_10_icons', '1'),
(11977, 566, '_full_width_components_10_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(11978, 566, 'full_width_components_10_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(11979, 566, '_full_width_components_10_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(11980, 566, 'full_width_components_11_text', 'Supporting Our Customers'),
(11981, 566, '_full_width_components_11_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(11982, 566, 'full_width_components_11_text_position', 'right'),
(11983, 566, '_full_width_components_11_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(11984, 566, 'full_width_components_11_background_image', '457'),
(11985, 566, '_full_width_components_11_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(11986, 566, 'full_width_components_12_two_column_content_0_column_style', 'image-left'),
(11987, 566, '_full_width_components_12_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(11988, 566, 'full_width_components_12_two_column_content_0_title', 'Support'),
(11989, 566, '_full_width_components_12_two_column_content_0_title', 'field_5ed8f3421c210'),
(11990, 566, 'full_width_components_12_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(11991, 566, '_full_width_components_12_two_column_content_0_text', 'field_5ed8f3421c225');
'),
