(13016, 576, 'full_width_components_6_text', 'Immersive Learning, Tomorrow’s Training Today'),
(13017, 576, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(13018, 576, 'full_width_components_6_text_position', 'right'),
