(13021, 576, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(13022, 576, 'full_width_components_7_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(13023, 576, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(13024, 576, 'full_width_components_7_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(13025, 576, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(13026, 576, 'full_width_components_7_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(13027, 576, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(13028, 576, 'full_width_components_7_buttons', ''),
(13029, 576, '_full_width_components_7_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(13030, 576, 'full_width_components_8_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(13031, 576, '_full_width_components_8_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(13032, 576, 'full_width_components_9_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
