(13056, 576, 'full_width_components_12_two_column_content_0_column_style', 'image-left'),
(13057, 576, '_full_width_components_12_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13058, 576, 'full_width_components_12_two_column_content_0_title', 'Support'),
(13059, 576, '_full_width_components_12_two_column_content_0_title', 'field_5ed8f3421c210'),
(13060, 576, 'full_width_components_12_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(13061, 576, '_full_width_components_12_two_column_content_0_text', 'field_5ed8f3421c225'),
(13062, 576, 'full_width_components_12_two_column_content_0_read_more_link', ''),
