(13365, 578, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(13366, 578, 'full_width_components_7_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(13367, 578, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(13368, 578, 'full_width_components_7_buttons', ''),
(13369, 578, '_full_width_components_7_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(13370, 578, 'full_width_components_8_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(13371, 578, '_full_width_components_8_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(13372, 578, 'full_width_components_9_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(13373, 578, '_full_width_components_9_buttons_0_button', 'field_5ed90856b39bb'),
(13374, 578, 'full_width_components_9_buttons_1_button', 'a:3:{s:5:\"title\";s:20:\"Book a Demonstration\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(13375, 578, '_full_width_components_9_buttons_1_button', 'field_5ed90856b39bb'),
(13376, 578, 'full_width_components_9_buttons', '2'),
(13377, 578, '_full_width_components_9_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(13378, 578, 'full_width_components_10_component_title', 'Immersive media - bringing creativity to life'),
(13379, 578, '_full_width_components_10_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(13380, 578, 'full_width_components_10_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(13381, 578, '_full_width_components_10_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(13382, 578, 'full_width_components_10_icons_0_icon', '504'),
(13383, 578, '_full_width_components_10_icons_0_icon', 'field_5ea984ddcbc5d'),
(13384, 578, 'full_width_components_10_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(13385, 578, '_full_width_components_10_icons_0_text', 'field_5ea984e6cbc5e'),
(13386, 578, 'full_width_components_10_icons', '1'),
(13387, 578, '_full_width_components_10_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(13388, 578, 'full_width_components_10_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(13389, 578, '_full_width_components_10_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(13390, 578, 'full_width_components_11_text', 'Supporting Our Customers'),
(13391, 578, '_full_width_components_11_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(13392, 578, 'full_width_components_11_text_position', 'center'),
(13393, 578, '_full_width_components_11_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(13394, 578, 'full_width_components_11_background_image', '457'),
(13395, 578, '_full_width_components_11_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(13396, 578, 'full_width_components_12_two_column_content_0_column_style', 'image-left'),
(13397, 578, '_full_width_components_12_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13398, 578, 'full_width_components_12_two_column_content_0_title', 'Support'),
(13399, 578, '_full_width_components_12_two_column_content_0_title', 'field_5ed8f3421c210'),
(13400, 578, 'full_width_components_12_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(13401, 578, '_full_width_components_12_two_column_content_0_text', 'field_5ed8f3421c225'),
(13402, 578, 'full_width_components_12_two_column_content_0_read_more_link', ''),
(13403, 578, '_full_width_components_12_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(13404, 578, 'full_width_components_12_two_column_content_0_image', '481'),
(13405, 578, '_full_width_components_12_two_column_content_0_image', 'field_5ed8f3421c23f'),
(13406, 578, 'full_width_components_12_two_column_content', '1'),
(13407, 578, '_full_width_components_12_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(13408, 578, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(13409, 578, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13410, 578, 'full_width_components_4_two_column_content_0_title', 'Facilitation'),
(13411, 578, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(13412, 578, 'full_width_components_4_two_column_content_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(13413, 578, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(13414, 578, 'full_width_components_4_two_column_content_0_read_more_link', ''),
(13415, 578, '_full_width_components_4_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(13416, 578, 'full_width_components_4_two_column_content_0_image', '493'),
(13417, 578, '_full_width_components_4_two_column_content_0_image', 'field_5ed8f3421c23f'),
(13418, 578, 'full_width_components_4_two_column_content_1_column_style', 'image-right'),
(13419, 578, '_full_width_components_4_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(13420, 578, 'full_width_components_4_two_column_content_1_title', 'The platform'),
(13421, 578, '_full_width_components_4_two_column_content_1_title', 'field_5ed8f3421c210'),
(13422, 578, 'full_width_components_4_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(13423, 578, '_full_width_components_4_two_column_content_1_text', 'field_5ed8f3421c225'),
(13424, 578, 'full_width_components_4_two_column_content_1_read_more_link', ''),
(13425, 578, '_full_width_components_4_two_column_content_1_read_more_link', 'field_5ed8f3421c235'),
(13426, 578, 'full_width_components_4_two_column_content_1_image', '496'),
(13427, 578, '_full_width_components_4_two_column_content_1_image', 'field_5ed8f3421c23f'),
(13428, 578, 'full_width_components_4_two_column_content_2_column_style', 'image-left'),
(13429, 578, '_full_width_components_4_two_column_content_2_column_style', 'field_5ed8f395410e1'),
(13430, 578, 'full_width_components_4_two_column_content_2_title', 'Virtual Conferencing'),
(13431, 578, '_full_width_components_4_two_column_content_2_title', 'field_5ed8f3421c210'),
(13432, 578, 'full_width_components_4_two_column_content_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(13433, 578, '_full_width_components_4_two_column_content_2_text', 'field_5ed8f3421c225'),
(13434, 578, 'full_width_components_4_two_column_content_2_read_more_link', ''),
