(13449, 364, '_full_width_components_2_two_column_content_0_image', 'field_5ed8f3421c23f'),
(13450, 364, 'full_width_components_2_two_column_content_1_column_style', 'image-left'),
(13451, 364, '_full_width_components_2_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(13452, 364, 'full_width_components_2_two_column_content_1_title', 'What was Achieved'),
(13453, 364, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(13454, 364, 'full_width_components_2_two_column_content_1_text', 'By delivering meaningful training using View360 Global for EXPOL’s clients we were able to provide them with a style of training that had not been experienced before by the participants. The consolidated experiential learning achieved and enjoyed by the participants evidenced value for money returned repeat business for EXPOL who continue to use the platform in their training programs'),
(13455, 364, '_full_width_components_2_two_column_content_1_text', 'field_5ed8f3421c225'),
