(15620, 608, 'full_width_components_2_text', 'Versatile and innovative learning, without geographical barriers '),
(15621, 608, '_full_width_components_2_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(15622, 608, 'full_width_components_2_text_position', 'center'),
(15623, 608, '_full_width_components_2_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(15624, 608, 'full_width_components_2_background_image', '492'),
(15625, 608, '_full_width_components_2_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(15626, 608, 'full_width_components_3_component_title', 'Sending your staff away for training can be both costly and disruptive to your organisation'),
(15627, 608, '_full_width_components_3_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(15628, 608, 'full_width_components_3_component_subtitle', 'With the functionality of allowing multiple internet enabled devices to be logged on at the same time, View360 Global™ can facilitate the delivery of training across multiple locations and allow your trainers to deliver onsite, regional or internationally from your organisation’s location. This provides a cost-effective option, as it brings the learning to the people and significantly reduces both travel costs and employee “down” time.'),
(15629, 608, '_full_width_components_3_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(15630, 608, 'full_width_components_3_content', 'The recent global crisis has indicated that learning will change in the future. The platform can provide the solution to bringing people that are located in different locations together without logistical complexity.\r\n\r\nCombined with using modern virtual conferencing platforms such a Zoom, MS Teams, WebEx or Google Hangouts View360 Global™ also enables people who speak different languages to participate more collaboratively with colleagues around the world.'),
(15631, 608, '_full_width_components_3_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(15632, 608, 'full_width_components_3_buttons', ''),
(15633, 608, '_full_width_components_3_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
