(15637, 608, '_full_width_components_5_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(15638, 608, 'full_width_components_6_text', 'Immersive Learning, Tomorrow’s Training Today'),
(15639, 608, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(15640, 608, 'full_width_components_6_text_position', 'center'),
(15641, 608, '_full_width_components_6_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(15642, 608, 'full_width_components_6_background_image', '499'),
(15643, 608, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(15644, 608, 'full_width_components_7_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(15645, 608, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(15646, 608, 'full_width_components_7_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(15647, 608, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(15648, 608, 'full_width_components_7_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(15649, 608, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(15650, 608, 'full_width_components_7_buttons', ''),
(15651, 608, '_full_width_components_7_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(15652, 608, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(15653, 608, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(15654, 608, 'full_width_components_4_two_column_content_0_title', 'Facilitation'),
(15655, 608, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(15656, 608, 'full_width_components_4_two_column_content_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(15657, 608, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(15658, 608, 'full_width_components_4_two_column_content_0_read_more_link', ''),
