(15663, 608, '_full_width_components_4_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(15664, 608, 'full_width_components_4_two_column_content_1_title', 'The platform'),
(15665, 608, '_full_width_components_4_two_column_content_1_title', 'field_5ed8f3421c210'),
(15666, 608, 'full_width_components_4_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(15667, 608, '_full_width_components_4_two_column_content_1_text', 'field_5ed8f3421c225'),
