(16737, 632, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(16738, 632, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(16739, 632, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(16740, 632, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(16741, 632, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(16742, 632, 'full_width_components_11_icons_0_icon', '504'),
(16743, 632, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(16744, 632, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(16745, 632, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(16746, 632, 'full_width_components_11_icons', '1'),
(16747, 632, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(16748, 632, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(16749, 632, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(16750, 632, 'full_width_components_12_text', 'Supporting Our Customers'),
(16751, 632, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(16752, 632, 'full_width_components_12_text_position', 'center'),
