(16779, 633, '_show_left_sidebar', 'field_5e38357452128'),
(16780, 633, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(16781, 633, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(16782, 633, 'full_width_components_0_component_title', 'Multilingual Data Capture'),
(16783, 633, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(16784, 633, 'full_width_components_0_component_subtitle', ''),
(16785, 633, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(16786, 633, 'full_width_components_0_content', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and\r\nafterwards, the record of activity provides clear evidence that desired outcomes have been met'),
(16787, 633, '_full_width_components_0_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(16788, 633, 'full_width_components_0_buttons', ''),
(16789, 633, '_full_width_components_0_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(16790, 633, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(16791, 633, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(16792, 633, 'full_width_components_1_two_column_content_0_title', ''),
(16793, 633, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(16794, 633, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(16795, 633, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(16796, 633, 'full_width_components_1_two_column_content_0_read_more_link', ''),
(16797, 633, '_full_width_components_1_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
