(19600, 665, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(19601, 665, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(19602, 665, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(19603, 665, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(19604, 665, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(19605, 665, 'full_width_components_11_icons_0_icon', '504'),
(19606, 665, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(19607, 665, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(19608, 665, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(19609, 665, 'full_width_components_11_icons', '1'),
(19610, 665, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(19611, 665, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(19612, 665, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(19613, 665, 'full_width_components_12_text', 'Supporting Our Customers'),
(19614, 665, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(19615, 665, 'full_width_components_12_text_position', 'center'),
(19616, 665, '_full_width_components_12_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(19617, 665, 'full_width_components_12_background_image', '457'),
(19618, 665, '_full_width_components_12_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(19619, 665, 'full_width_components_13_two_column_content_0_column_style', 'image-right'),
(19620, 665, '_full_width_components_13_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(19621, 665, 'full_width_components_13_two_column_content_0_title', ''),
(19622, 665, '_full_width_components_13_two_column_content_0_title', 'field_5ed8f3421c210'),
(19623, 665, 'full_width_components_13_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(19624, 665, '_full_width_components_13_two_column_content_0_text', 'field_5ed8f3421c225'),
(19625, 665, 'full_width_components_13_two_column_content_0_read_more_link', ''),
