(19839, 667, 'show_left_sidebar', '0'),
(19840, 667, '_show_left_sidebar', 'field_5e38357452128'),
(19841, 667, 'components_0_component_title', 'Our easy to use platform drives innovative digital learning'),
(19842, 667, '_components_0_component_title', 'field_5ebd0548c3669_field_5ebd01f5d7bfb'),
(19843, 667, 'components_0_component_summary', ''),
(19844, 667, '_components_0_component_summary', 'field_5ebd0548c3669_field_5ebd071af49f2'),
(19845, 667, 'components_0_timeline_items_0_timeline_title', 'User Friendly'),
(19846, 667, '_components_0_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(19847, 667, 'components_0_timeline_items_0_timeline_content', 'The View360 Global™ platform is easy-to-use and requires no complex IT infrastructure, just a PC, laptop or tablet. Meanwhile, our simple ‘point, click and type’ functionality keeps the emphasis on learning rather than navigating complicated operational features. <br><br>  In a single one-to-one training session, our experts will give your facilitators the skills they need to use the platform confidently. We also provide  additional support with online tutorials. '),
(19848, 667, '_components_0_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(19849, 667, 'components_0_timeline_items_1_timeline_title', 'Remote Delivery'),
(19850, 667, '_components_0_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd');
'),
(19872, 667, '_full_width_components_0_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(19873, 667, 'full_width_components_0_timeline_items_0_timeline_content', 'User Friendly The View360 Global™ platform is easy-to-use and requires no complex IT infrastructure, just a PC, laptop or tablet. Meanwhile, our simple ‘point, click and type’ functionality keeps the emphasis on learning rather than navigating complicated operational features.  <br><br> In a single one-to-one training session, our experts will give your facilitators the skills they need to use the platform confidently. We also provide additional support with online tutorials. '),
(19874, 667, '_full_width_components_0_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(19875, 667, 'full_width_components_0_timeline_items_1_timeline_title', 'Remote Delivery'),
(19876, 667, '_full_width_components_0_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(19877, 667, 'full_width_components_0_timeline_items_1_timeline_content', 'The versatile design of our platform allows for cloud-based delivery. This makes it possible for learning to take place in a local environment or remotely, with participants located anywhere in the world.  <br><br>  This enables you to deliver cost-effective solutions that reach more people, while avoiding the disruption of offsite training days '),
(19878, 667, '_full_width_components_0_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(19879, 667, 'full_width_components_0_timeline_items_2_timeline_title', 'Security '),
(19880, 667, '_full_width_components_0_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(19881, 667, 'full_width_components_0_timeline_items_2_timeline_content', 'The platform is available either as a cloud-based application that stores data using Amazon Web Space (AWS) services or or through a Local Area Network (LAN) . It can be delivered through a  secure HTTPS URL and private VPN into Chrome or Firefox browsers and is compatible with all video conferencing systems. <br><br> Our backend architecture and use adheres to guidelines set out by the UK National Cyber Security Centre (NCSC) for the implementation of the Cloud Security Principles and the Government Digital Service, Technology Code of Practice'),
(19882, 667, '_full_width_components_0_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(19883, 667, 'full_width_components_0_timeline_items_3_timeline_title', 'Multilingual'),
(19884, 667, '_full_width_components_0_timeline_items_3_timeline_title', 'field_5ebd0237d7bfd'),
(19885, 667, 'full_width_components_0_timeline_items_3_timeline_content', 'Use of the platform’s advanced translation API means that sessions can be conducted in over 90 languages. The ability to have multinational participants online at the same time opens up the potential for meaningful and inclusive learning across the globe.'),
(19886, 667, '_full_width_components_0_timeline_items_3_timeline_content', 'field_5ebd023fd7bfe'),
(19887, 667, 'full_width_components_0_timeline_items_4_timeline_title', 'Data Capture'),
(19888, 667, '_full_width_components_0_timeline_items_4_timeline_title', 'field_5ebd0237d7bfd'),
(19889, 667, 'full_width_components_0_timeline_items_4_timeline_content', 'View360 Global captures all learning activity in native and translated languages and automatically formats the data into MS Word format. This can be used for any independent or external quality assurance or assessment processes. '),
(19890, 667, '_full_width_components_0_timeline_items_4_timeline_content', 'field_5ebd023fd7bfe'),
(19891, 667, 'full_width_components_0_timeline_items', '5'),
(19892, 667, '_full_width_components_0_timeline_items', 'field_5ed7645bb169a_field_5ebd0228d7bfc'),
(19893, 667, 'full_width_components_1_buttons_0_button', 'a:3:{s:5:\"title\";s:11:\"Book a demo\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(19894, 667, '_full_width_components_1_buttons_0_button', 'field_5ed90856b39bb'),
(19895, 667, 'full_width_components_1_buttons', '1'),
(19896, 667, '_full_width_components_1_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(19897, 667, 'full_width_components_2_text', 'Versatile and innovative learning, without geographical barriers '),
(19898, 667, '_full_width_components_2_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(19899, 667, 'full_width_components_2_text_position', 'center'),
(19900, 667, '_full_width_components_2_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(19901, 667, 'full_width_components_2_background_image', '492'),
(19902, 667, '_full_width_components_2_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(19903, 667, 'full_width_components_3_component_title', 'Sending your staff away for training can be both costly and disruptive to your organisation'),
(19904, 667, '_full_width_components_3_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(19905, 667, 'full_width_components_3_component_subtitle', 'With the functionality of allowing multiple internet enabled devices to be logged on at the same time, View360 Global™ can facilitate the delivery of training across multiple locations and allow your trainers to deliver onsite, regional or internationally from your organisation’s location. This provides a cost-effective option, as it brings the learning to the people and significantly reduces both travel costs and employee “down” time.'),
(19906, 667, '_full_width_components_3_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(19907, 667, 'full_width_components_3_content', 'The recent global crisis has indicated that learning will change in the future. The platform can provide the solution to bringing people that are located in different locations together without logistical complexity.\r\n\r\nCombined with using modern virtual conferencing platforms such a Zoom, MS Teams, WebEx or Google Hangouts View360 Global™ also enables people who speak different languages to participate more collaboratively with colleagues around the world.'),
(19908, 667, '_full_width_components_3_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(19909, 667, 'full_width_components_3_buttons', ''),
(19910, 667, '_full_width_components_3_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(19911, 667, 'full_width_components_5_buttons_0_button', 'a:3:{s:5:\"title\";s:11:\"Book a demo\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(19912, 667, '_full_width_components_5_buttons_0_button', 'field_5ed90856b39bb'),
(19913, 667, 'full_width_components_5_buttons', '1'),
(19914, 667, '_full_width_components_5_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(19915, 667, 'full_width_components_6_text', 'Immersive Learning, Tomorrow’s Training Today'),
(19916, 667, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(19917, 667, 'full_width_components_6_text_position', 'center'),
(19918, 667, '_full_width_components_6_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(19919, 667, 'full_width_components_6_background_image', '499'),
(19920, 667, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(19921, 667, 'full_width_components_7_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(19922, 667, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(19923, 667, 'full_width_components_7_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(19924, 667, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(19925, 667, 'full_width_components_7_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(19926, 667, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(19927, 667, 'full_width_components_7_buttons', ''),
(19928, 667, '_full_width_components_7_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(19929, 667, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(19930, 667, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(19931, 667, 'full_width_components_4_two_column_content_0_title', 'Facilitation'),
(19932, 667, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(19933, 667, 'full_width_components_4_two_column_content_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(19934, 667, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(19935, 667, 'full_width_components_4_two_column_content_0_read_more_link', ''),
(19936, 667, '_full_width_components_4_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(19937, 667, 'full_width_components_4_two_column_content_0_image', '649'),
(19938, 667, '_full_width_components_4_two_column_content_0_image', 'field_5ed8f3421c23f'),
(19939, 667, 'full_width_components_4_two_column_content_1_column_style', 'image-right'),
(19940, 667, '_full_width_components_4_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(19941, 667, 'full_width_components_4_two_column_content_1_title', 'The platform'),
(19942, 667, '_full_width_components_4_two_column_content_1_title', 'field_5ed8f3421c210'),
(19943, 667, 'full_width_components_4_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(19944, 667, '_full_width_components_4_two_column_content_1_text', 'field_5ed8f3421c225'),
(19945, 667, 'full_width_components_4_two_column_content_1_read_more_link', ''),
(19946, 667, '_full_width_components_4_two_column_content_1_read_more_link', 'field_5ed8f3421c235'),
(19947, 667, 'full_width_components_4_two_column_content_1_image', '496'),
(19948, 667, '_full_width_components_4_two_column_content_1_image', 'field_5ed8f3421c23f'),
(19949, 667, 'full_width_components_4_two_column_content_2_column_style', 'image-left'),
(19950, 667, '_full_width_components_4_two_column_content_2_column_style', 'field_5ed8f395410e1'),
(19951, 667, 'full_width_components_4_two_column_content_2_title', 'Virtual Conferencing'),
(19952, 667, '_full_width_components_4_two_column_content_2_title', 'field_5ed8f3421c210'),
(19953, 667, 'full_width_components_4_two_column_content_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(19954, 667, '_full_width_components_4_two_column_content_2_text', 'field_5ed8f3421c225'),
(19955, 667, 'full_width_components_4_two_column_content_2_read_more_link', ''),
(19956, 667, '_full_width_components_4_two_column_content_2_read_more_link', 'field_5ed8f3421c235'),
