(19996, 667, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(19997, 667, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(19998, 667, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(19999, 667, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(20000, 667, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(20001, 667, 'full_width_components_11_icons_0_icon', '504'),
(20002, 667, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(20003, 667, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(20004, 667, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(20005, 667, 'full_width_components_11_icons', '1'),
(20006, 667, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(20007, 667, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(20008, 667, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(20009, 667, 'full_width_components_12_text', 'Supporting Our Customers'),
(20010, 667, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(20011, 667, 'full_width_components_12_text_position', 'center'),
