(20014, 667, '_full_width_components_12_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(20015, 667, 'full_width_components_13_two_column_content_0_column_style', 'image-right'),
(20016, 667, '_full_width_components_13_two_column_content_0_column_style', 'field_5ed8f395410e1'),
