(20267, 672, 'components_0_component_title', 'Our easy to use platform drives innovative digital learning'),
(20268, 672, '_components_0_component_title', 'field_5ebd0548c3669_field_5ebd01f5d7bfb'),
(20269, 672, 'components_0_component_summary', ''),
(20270, 672, '_components_0_component_summary', 'field_5ebd0548c3669_field_5ebd071af49f2'),
(20271, 672, 'components_0_timeline_items_0_timeline_title', 'User Friendly'),
(20272, 672, '_components_0_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(20273, 672, 'components_0_timeline_items_0_timeline_content', 'The View360 Global™ platform is easy-to-use and requires no complex IT infrastructure, just a PC, laptop or tablet. Meanwhile, our simple ‘point, click and type’ functionality keeps the emphasis on learning rather than navigating complicated operational features. <br><br>  In a single one-to-one training session, our experts will give your facilitators the skills they need to use the platform confidently. We also provide  additional support with online tutorials. '),
(20274, 672, '_components_0_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(20275, 672, 'components_0_timeline_items_1_timeline_title', 'Remote Delivery'),
(20276, 672, '_components_0_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(20277, 672, 'components_0_timeline_items_1_timeline_content', 'The versatile design of our platform allows for cloud-based delivery. This makes it possible for learning to take place in a local environment or remotely, with participants located anywhere in the world.  <br><br>  This enables you to deliver cost-effective solutions that reach more people, while avoiding the disruption of offsite training days '),
(20278, 672, '_components_0_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(20279, 672, 'components_0_timeline_items_2_timeline_title', 'Security ');
'),
(20472, 673, '_components_0_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(20473, 673, 'components_0_timeline_items_0_timeline_content', 'The View360 Global™ platform is easy-to-use and requires no complex IT infrastructure, just a PC, laptop or tablet. Meanwhile, our simple ‘point, click and type’ functionality keeps the emphasis on learning rather than navigating complicated operational features. <br><br>  In a single one-to-one training session, our experts will give your facilitators the skills they need to use the platform confidently. We also provide  additional support with online tutorials. '),
