(20620, 673, '_full_width_components_10_buttons_1_button', 'field_5ed90856b39bb'),
(20621, 673, 'full_width_components_10_buttons', '2'),
(20622, 673, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(20623, 673, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(20624, 673, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(20625, 673, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(20626, 673, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(20627, 673, 'full_width_components_11_icons_0_icon', '504'),
(20628, 673, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(20629, 673, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(20630, 673, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(20631, 673, 'full_width_components_11_icons', '1'),
(20632, 673, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(20633, 673, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(20634, 673, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(20635, 673, 'full_width_components_12_text', 'Supporting Our Customers'),
(20636, 673, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(20637, 673, 'full_width_components_12_text_position', 'center'),
(20638, 673, '_full_width_components_12_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(20639, 673, 'full_width_components_12_background_image', '457'),
(20640, 673, '_full_width_components_12_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(20641, 673, 'full_width_components_13_two_column_content_0_column_style', 'image-right'),
(20642, 673, '_full_width_components_13_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(20643, 673, 'full_width_components_13_two_column_content_0_title', ''),
(20644, 673, '_full_width_components_13_two_column_content_0_title', 'field_5ed8f3421c210'),
(20645, 673, 'full_width_components_13_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(20646, 673, '_full_width_components_13_two_column_content_0_text', 'field_5ed8f3421c225'),
(20647, 673, 'full_width_components_13_two_column_content_0_read_more_link', ''),
