(20724, 674, '_full_width_components', 'field_5e3bd2cd0cde3'),
(20725, 674, 'show_left_sidebar', '0'),
(20726, 674, '_show_left_sidebar', 'field_5e38357452128'),
(20727, 674, 'components_0_component_title', 'Our easy to use platform drives innovative digital learning'),
(20728, 674, '_components_0_component_title', 'field_5ebd0548c3669_field_5ebd01f5d7bfb'),
(20729, 674, 'components_0_component_summary', ''),
(20730, 674, '_components_0_component_summary', 'field_5ebd0548c3669_field_5ebd071af49f2'),
(20731, 674, 'components_0_timeline_items_0_timeline_title', 'User Friendly'),
(20732, 674, '_components_0_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(20733, 674, 'components_0_timeline_items_0_timeline_content', 'The View360 Global™ platform is easy-to-use and requires no complex IT infrastructure, just a PC, laptop or tablet. Meanwhile, our simple ‘point, click and type’ functionality keeps the emphasis on learning rather than navigating complicated operational features. <br><br>  In a single one-to-one training session, our experts will give your facilitators the skills they need to use the platform confidently. We also provide  additional support with online tutorials. '),
(20734, 674, '_components_0_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(20735, 674, 'components_0_timeline_items_1_timeline_title', 'Remote Delivery'),
(20736, 674, '_components_0_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(20737, 674, 'components_0_timeline_items_1_timeline_content', 'The versatile design of our platform allows for cloud-based delivery. This makes it possible for learning to take place in a local environment or remotely, with participants located anywhere in the world.  <br><br>  This enables you to deliver cost-effective solutions that reach more people, while avoiding the disruption of offsite training days '),
(20738, 674, '_components_0_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(20739, 674, 'components_0_timeline_items_2_timeline_title', 'Security '),
(20740, 674, '_components_0_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(20741, 674, 'components_0_timeline_items_2_timeline_content', ' The platform is available either as a cloud-based application that stores data using Amazon Web Space (AWS) services or or through a Local Area Network (LAN) . It can be delivered through a  secure HTTPS URL and private VPN into Chrome or Firefox browsers and is compatible with all video conferencing systems. <br><br>  Our backend architecture and use adheres to guidelines set out by the UK National Cyber Security Centre (NCSC) for the implementation of the Cloud Security Principles and the Government Digital Service, Technology Code of Practice'),
(20742, 674, '_components_0_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(20743, 674, 'components_0_timeline_items_3_timeline_title', 'Multilingual'),
(20744, 674, '_components_0_timeline_items_3_timeline_title', 'field_5ebd0237d7bfd'),
(20745, 674, 'components_0_timeline_items_3_timeline_content', 'Use of the platform’s advanced translation API means that sessions can be conducted in over 90 languages. The ability to have multinational participants online at the same time opens up the potential for meaningful and inclusive learning across the globe.'),
(20746, 674, '_components_0_timeline_items_3_timeline_content', 'field_5ebd023fd7bfe'),
(20747, 674, 'components_0_timeline_items_4_timeline_title', 'Data Capture'),
(20748, 674, '_components_0_timeline_items_4_timeline_title', 'field_5ebd0237d7bfd'),
(20749, 674, 'components_0_timeline_items_4_timeline_content', 'View360 Global captures all learning activity in native and translated languages and automatically formats the data into MS Word format. This can be used for any independent or external quality assurance or assessment processes.'),
(20750, 674, '_components_0_timeline_items_4_timeline_content', 'field_5ebd023fd7bfe'),
(20751, 674, 'components_0_timeline_items', '5'),
(20752, 674, '_components_0_timeline_items', 'field_5ebd0548c3669_field_5ebd0228d7bfc'),
(20753, 674, 'full_width_components_0_text', 'Immersive Learning, Tomorrow’s Training Today'),
(20754, 674, '_full_width_components_0_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(20755, 674, 'full_width_components_0_text_position', 'center'),
(20756, 674, '_full_width_components_0_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(20757, 674, 'full_width_components_0_background_image', '499'),
(20758, 674, '_full_width_components_0_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(20759, 674, 'full_width_components_1_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(20760, 674, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(20761, 674, 'full_width_components_1_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(20762, 674, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(20763, 674, 'full_width_components_1_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(20764, 674, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(20765, 674, 'full_width_components_1_buttons', ''),
