(21006, 676, '_full_width_components_0_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(21007, 676, 'full_width_components_1_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(21008, 676, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(21009, 676, 'full_width_components_1_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(21010, 676, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(21011, 676, 'full_width_components_1_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
