(21049, 676, 'full_width_components_5_component_title', 'Immersive media - bringing creativity to life'),
(21050, 676, '_full_width_components_5_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(21051, 676, 'full_width_components_5_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(21052, 676, '_full_width_components_5_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(21053, 676, 'full_width_components_5_icons_0_icon', '504'),
(21054, 676, '_full_width_components_5_icons_0_icon', 'field_5ea984ddcbc5d'),
(21055, 676, 'full_width_components_5_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(21056, 676, '_full_width_components_5_icons_0_text', 'field_5ea984e6cbc5e'),
(21057, 676, 'full_width_components_5_icons', '1'),
