(21305, 679, 'full_width_components_2_component_title', 'Measuring the impact of your learning'),
(21306, 679, '_full_width_components_2_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(21307, 679, 'full_width_components_2_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(21308, 679, '_full_width_components_2_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(21309, 679, 'full_width_components_2_content', '<img class=\"alignnone size-large wp-image-508\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.52.50-e1590749697636-1024x422.png\" alt=\"\" width=\"1024\" height=\"422\" />'),
(21310, 679, '_full_width_components_2_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
