(23852, 700, '_full_width_components_1_gallery_items', 'field_5ed763b6b1690_field_5d8dbaaa76571'),
(23853, 700, 'full_width_components_2_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(23854, 700, '_full_width_components_2_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(23855, 700, 'full_width_components_3_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
