(23858, 700, '_full_width_components_3_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(23859, 700, 'full_width_components_4_component_title', 'Immersive media - bringing creativity to life'),
(23860, 700, '_full_width_components_4_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(23861, 700, 'full_width_components_4_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(23862, 700, '_full_width_components_4_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(23863, 700, 'full_width_components_4_icons_0_icon', '504'),
(23864, 700, '_full_width_components_4_icons_0_icon', 'field_5ea984ddcbc5d'),
(23865, 700, 'full_width_components_4_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(23866, 700, '_full_width_components_4_icons_0_text', 'field_5ea984e6cbc5e'),
(23867, 700, 'full_width_components_4_icons', '1'),
(23868, 700, '_full_width_components_4_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(23869, 700, 'full_width_components_4_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(23870, 700, '_full_width_components_4_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
