(23924, 702, '_full_width_components_0_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(23925, 702, 'full_width_components_0_timeline_items_2_timeline_title', 'Security '),
(23926, 702, '_full_width_components_0_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(23927, 702, 'full_width_components_0_timeline_items_2_timeline_content', 'The platform is available either as a cloud-based application that stores data using Amazon Web Space (AWS) services or or through a Local Area Network (LAN) . It can be delivered through a  secure HTTPS URL and private VPN into Chrome or Firefox browsers and is compatible with all video conferencing systems. <br><br> Our backend architecture and use adheres to guidelines set out by the UK National Cyber Security Centre (NCSC) for the implementation of the Cloud Security Principles and the Government Digital Service, Technology Code of Practice'),
(23928, 702, '_full_width_components_0_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(23929, 702, 'full_width_components_0_timeline_items_3_timeline_title', 'Multilingual'),
(23930, 702, '_full_width_components_0_timeline_items_3_timeline_title', 'field_5ebd0237d7bfd'),
(23931, 702, 'full_width_components_0_timeline_items_3_timeline_content', 'Use of the platform’s advanced translation API means that sessions can be conducted in over 90 languages. The ability to have multinational participants online at the same time opens up the potential for meaningful and inclusive learning across the globe.'),
(23932, 702, '_full_width_components_0_timeline_items_3_timeline_content', 'field_5ebd023fd7bfe'),
