(23942, 702, '_full_width_components_1_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(23943, 702, 'full_width_components_2_text', 'Versatile and innovative learning, without geographical barriers '),
(23944, 702, '_full_width_components_2_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(23945, 702, 'full_width_components_2_text_position', 'center'),
(23946, 702, '_full_width_components_2_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(23947, 702, 'full_width_components_2_background_image', '492'),
(23948, 702, '_full_width_components_2_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(23949, 702, 'full_width_components_3_component_title', 'Sending your staff away for training can be both costly and disruptive to your organisation'),
(23950, 702, '_full_width_components_3_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(23951, 702, 'full_width_components_3_component_subtitle', 'With the functionality of allowing multiple internet enabled devices to be logged on at the same time, View360 Global™ can facilitate the delivery of training across multiple locations and allow your trainers to deliver onsite, regional or internationally from your organisation’s location. This provides a cost-effective option, as it brings the learning to the people and significantly reduces both travel costs and employee “down” time.'),
(23952, 702, '_full_width_components_3_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(23953, 702, 'full_width_components_3_content', 'The recent global crisis has indicated that learning will change in the future. The platform can provide the solution to bringing people that are located in different locations together without logistical complexity.\r\n\r\nCombined with using modern virtual conferencing platforms such a Zoom, MS Teams, WebEx or Google Hangouts View360 Global™ also enables people who speak different languages to participate more collaboratively with colleagues around the world.'),
(23954, 702, '_full_width_components_3_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(23955, 702, 'full_width_components_3_buttons', ''),
(23956, 702, '_full_width_components_3_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(23957, 702, 'full_width_components_5_buttons_0_button', 'a:3:{s:5:\"title\";s:11:\"Book a demo\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
