(23966, 702, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(23967, 702, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(23968, 702, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(23969, 702, 'full_width_components_4_two_column_content_0_title', 'Facilitation'),
(23970, 702, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(23971, 702, 'full_width_components_4_two_column_content_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(23972, 702, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(23973, 702, 'full_width_components_4_two_column_content_0_read_more_link', ''),
(23974, 702, '_full_width_components_4_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(23975, 702, 'full_width_components_4_two_column_content_0_image', '649'),
(23976, 702, '_full_width_components_4_two_column_content_0_image', 'field_5ed8f3421c23f'),
(23977, 702, 'full_width_components_4_two_column_content_1_column_style', 'image-right'),
(23978, 702, '_full_width_components_4_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(23979, 702, 'full_width_components_4_two_column_content_1_title', 'The platform'),
(23980, 702, '_full_width_components_4_two_column_content_1_title', 'field_5ed8f3421c210'),
(23981, 702, 'full_width_components_4_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(23982, 702, '_full_width_components_4_two_column_content_1_text', 'field_5ed8f3421c225'),
(23983, 702, 'full_width_components_4_two_column_content_1_read_more_link', ''),
(23984, 702, '_full_width_components_4_two_column_content_1_read_more_link', 'field_5ed8f3421c235'),
(23985, 702, 'full_width_components_4_two_column_content_1_image', '496'),
(23986, 702, '_full_width_components_4_two_column_content_1_image', 'field_5ed8f3421c23f'),
(23987, 702, 'full_width_components_4_two_column_content_2_column_style', 'image-left'),
(23988, 702, '_full_width_components_4_two_column_content_2_column_style', 'field_5ed8f395410e1'),
(23989, 702, 'full_width_components_4_two_column_content_2_title', 'Virtual Conferencing'),
(23990, 702, '_full_width_components_4_two_column_content_2_title', 'field_5ed8f3421c210'),
(23991, 702, 'full_width_components_4_two_column_content_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(23992, 702, '_full_width_components_4_two_column_content_2_text', 'field_5ed8f3421c225'),
(23993, 702, 'full_width_components_4_two_column_content_2_read_more_link', ''),
