(23999, 702, 'full_width_components_7_two_column_content_0_column_style', 'image-right'),
(24000, 702, '_full_width_components_7_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(24001, 702, 'full_width_components_7_two_column_content_0_title', ''),
(24002, 702, '_full_width_components_7_two_column_content_0_title', 'field_5ed8f3421c210'),
(24003, 702, 'full_width_components_7_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(24004, 702, '_full_width_components_7_two_column_content_0_text', 'field_5ed8f3421c225'),
(24005, 702, 'full_width_components_7_two_column_content_0_read_more_link', ''),
