(24015, 7, 'full_width_components_0_component_title', 'Cognitas Global Ltd aims to prompt a paradigm shift in education, learning & development for the private and public sectors with the multilingual immersive training platform View360 Global™. '),
(24016, 7, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(24017, 7, 'full_width_components_0_component_subtitle', 'Our vision is to offer ground-breaking cost effective and sustainable blended learning solutions '),
(24018, 7, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
