(24214, 703, '_full_width_components_3_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(24215, 703, 'full_width_components_3_alternating_image_text_0_title', 'Our Team'),
(24216, 703, '_full_width_components_3_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(24217, 703, 'full_width_components_3_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(24218, 703, '_full_width_components_3_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(24219, 703, 'full_width_components_3_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(24220, 703, '_full_width_components_3_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(24221, 703, 'full_width_components_3_alternating_image_text_0_image', '334'),
(24222, 703, '_full_width_components_3_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(24223, 703, 'full_width_components_3_alternating_image_text_1_title', 'Our Philosophy'),
(24224, 703, '_full_width_components_3_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(24225, 703, 'full_width_components_3_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(24226, 703, '_full_width_components_3_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(24227, 703, 'full_width_components_3_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(24228, 703, '_full_width_components_3_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(24229, 703, 'full_width_components_3_alternating_image_text_1_image', '335'),
(24230, 703, '_full_width_components_3_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(24231, 703, 'full_width_components_3_alternating_image_text_2_title', 'Our Training Credentials'),
(24232, 703, '_full_width_components_3_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(24233, 703, 'full_width_components_3_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(24234, 703, '_full_width_components_3_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(24235, 703, 'full_width_components_3_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
