(24238, 703, '_full_width_components_3_alternating_image_text_2_image', 'field_5e70f0ef0dfd6'),
(24239, 703, 'full_width_components_3_alternating_image_text', '3'),
(24240, 703, '_full_width_components_3_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(24241, 703, 'full_width_components_4_reduce_image_sizes', 'larger-images'),
(24242, 703, '_full_width_components_4_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(24243, 703, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(24244, 703, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(24245, 703, 'full_width_components_4_two_column_content_0_title', ''),
(24246, 703, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(24247, 703, 'full_width_components_4_two_column_content_0_text', 'Before Cognitas Global was founded in 2018, we built our experience on delivering capacity building, training and technical assistance in 54 countries through our parent company <u>AML Consulting (Global).</u>\r\n\r\nSince 2011, we’ve worked with numerous clients, including the UK Foreign &amp; Commonwealth Office, Department for International Development (DfID), UK National Crime Agency and National Economic Crime Centre, the United Nations Office for Drugs &amp; Crime (UNODC), and the Organisation for Security and Cooperation in Europe (OSCE).\r\n\r\nMeanwhile, our sister company AML Consulting (Global) UK has held SFJ Approved Training Centre status since 2017. It leads on the design and global delivery of Skills for Justice Awards accredited training programmes.'),
(24248, 703, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(24249, 703, 'full_width_components_4_two_column_content_0_read_more_link', ''),
