(25764, 714, '_full_width_components', 'field_5e3bd2cd0cde3'),
(25765, 714, 'show_left_sidebar', '0'),
(25766, 714, '_show_left_sidebar', 'field_5e38357452128'),
(25767, 714, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(25768, 714, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
