(25773, 714, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(25774, 714, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(25775, 714, 'full_width_components_1_two_column_content_0_read_more_link', ''),
