(25820, 714, '_full_width_components_1_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(25821, 714, 'full_width_components_0_content', '<h1 style=\"text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</h1>\r\n<h2 style=\"text-align: center;\">Multilingual Data Capture</h2>\r\n<p style=\"text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met</p>'),
(25822, 714, '_full_width_components_0_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(25823, 715, 'page_title_override', ''),
