(26101, 716, 'full_width_components_5_two_column_content_1_title', 'The platform'),
(26102, 716, '_full_width_components_5_two_column_content_1_title', 'field_5ed8f3421c210'),
(26103, 716, 'full_width_components_5_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(26104, 716, '_full_width_components_5_two_column_content_1_text', 'field_5ed8f3421c225'),
