(26237, 717, 'full_width_components_2_text', 'Versatile and innovative learning, without geographical barriers '),
(26238, 717, '_full_width_components_2_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(26239, 717, 'full_width_components_2_text_position', 'center'),
(26240, 717, '_full_width_components_2_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(26241, 717, 'full_width_components_2_background_image', '492'),
(26242, 717, '_full_width_components_2_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(26243, 717, 'full_width_components_3_component_title', 'Sending your staff away for training can be both costly and disruptive to your organisation'),
(26244, 717, '_full_width_components_3_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(26245, 717, 'full_width_components_3_component_subtitle', 'With the functionality of allowing multiple internet enabled devices to be logged on at the same time, View360 Global™ can facilitate the delivery of training across multiple locations and allow your trainers to deliver onsite, regional or internationally from your organisation’s location. This provides a cost-effective option, as it brings the learning to the people and significantly reduces both travel costs and employee “down” time.'),
(26246, 717, '_full_width_components_3_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(26247, 717, 'full_width_components_3_content', 'The recent global crisis has indicated that learning will change in the future. The platform can provide the solution to bringing people that are located in different locations together without logistical complexity.\r\n\r\nCombined with using modern virtual conferencing platforms such a Zoom, MS Teams, WebEx or Google Hangouts View360 Global™ also enables people who speak different languages to participate more collaboratively with colleagues around the world.'),
(26248, 717, '_full_width_components_3_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(26249, 717, 'full_width_components_3_buttons', ''),
(26250, 717, '_full_width_components_3_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(26251, 717, 'full_width_components_4_component_title', ''),
(26252, 717, '_full_width_components_4_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(26253, 717, 'full_width_components_4_alternating_image_text_0_title', 'Facilitation'),
(26254, 717, '_full_width_components_4_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(26255, 717, 'full_width_components_4_alternating_image_text_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(26256, 717, '_full_width_components_4_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(26257, 717, 'full_width_components_4_alternating_image_text_0_read_more_link', ''),
