(27187, 428, 'full_width_components_2_component_title', 'Measuring the impact of your learning'),
(27188, 428, '_full_width_components_2_component_title', 'field_5ef318287c995_field_5ef317911c4c5'),
(27189, 428, 'full_width_components_2_component_summary', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
