(27263, 765, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(27264, 765, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(27265, 765, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(27266, 765, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(27267, 765, 'full_width_components_1_two_column_content_0_title', ''),
(27268, 765, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(27269, 765, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(27270, 765, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(27271, 765, 'full_width_components_1_two_column_content_0_read_more_link', ''),
(27272, 765, '_full_width_components_1_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(27273, 765, 'full_width_components_1_two_column_content_0_image', '310'),
(27274, 765, '_full_width_components_1_two_column_content_0_image', 'field_5ed8f3421c23f'),
(27275, 765, 'full_width_components_1_two_column_content_1_column_style', 'image-right'),
(27276, 765, '_full_width_components_1_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(27277, 765, 'full_width_components_1_two_column_content_1_title', ''),
(27278, 765, '_full_width_components_1_two_column_content_1_title', 'field_5ed8f3421c210'),
(27279, 765, 'full_width_components_1_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
(27280, 765, '_full_width_components_1_two_column_content_1_text', 'field_5ed8f3421c225'),
(27281, 765, 'full_width_components_1_two_column_content_1_read_more_link', ''),
