(30692, 814, 'full_width_components_0_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(30693, 814, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(30694, 814, 'full_width_components_0_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(30695, 814, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(30696, 814, 'full_width_components_0_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-500 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.37.18-1024x382.png\" alt=\"\" width=\"1024\" height=\"382\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
