(30728, 814, 'full_width_components_2_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(30729, 814, '_full_width_components_2_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(30730, 814, 'full_width_components_3_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(30731, 814, '_full_width_components_3_buttons_0_button', 'field_5ed90856b39bb'),
(30732, 814, 'full_width_components_3_buttons', '1'),
(30733, 814, '_full_width_components_3_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(30734, 814, 'full_width_components_4_component_title', 'Immersive media - bringing creativity to life'),
(30735, 814, '_full_width_components_4_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(30736, 814, 'full_width_components_4_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(30737, 814, '_full_width_components_4_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(30738, 814, 'full_width_components_4_icons_0_icon', '812'),
(30739, 814, '_full_width_components_4_icons_0_icon', 'field_5ea984ddcbc5d'),
(30740, 814, 'full_width_components_4_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(30741, 814, '_full_width_components_4_icons_0_text', 'field_5ea984e6cbc5e'),
(30742, 814, 'full_width_components_4_icons', '1'),
(30743, 814, '_full_width_components_4_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(30744, 814, 'full_width_components_4_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(30745, 814, '_full_width_components_4_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(30746, 815, 'page_title_override', ''),
