(30755, 815, '_full_width_components', 'field_5e3bd2cd0cde3'),
(30756, 815, 'show_left_sidebar', '0'),
(30757, 815, '_show_left_sidebar', 'field_5e38357452128'),
(30758, 815, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(30759, 815, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(30760, 815, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(30761, 815, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(30762, 815, 'full_width_components_1_two_column_content_0_title', ''),
(30763, 815, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(30764, 815, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(30765, 815, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(30766, 815, 'full_width_components_1_two_column_content_0_read_more_link', ''),
