(30785, 815, '_full_width_components_0_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(30786, 815, 'full_width_components_2_component_title', 'Measuring the impact of your learning'),
(30787, 815, '_full_width_components_2_component_title', 'field_5ef318287c995_field_5ef317911c4c5'),
(30788, 815, 'full_width_components_2_component_summary', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
