(30857, 816, '_show_left_sidebar', 'field_5e38357452128'),
(30858, 816, 'full_width_components_0_two_column_content_0_column_style', 'image-right'),
(30859, 816, '_full_width_components_0_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(30860, 816, 'full_width_components_0_two_column_content_0_title', 'You lead – we listen, support and advise '),
(30861, 816, '_full_width_components_0_two_column_content_0_title', 'field_5ed8f3421c210'),
(30862, 816, 'full_width_components_0_two_column_content_0_text', 'We know our clients want meaningful, cost-effective learning solutions. Exactly what that looks like depends on your specific objectives, timeframes and budget. We’ll spend time getting a clear understanding of what those are.\r\n\r\nWith our established Learning and Development credentials, we have the expertise to help you turn your objectives into a clear strategy. You’ll be able to deliver a meaningful learning experience that engages your audience and supports their progress, both individually and, if applicable, as part of a team.\r\n\r\n<b>Are you paying an annual licence for our platform? </b>\r\n\r\nYou can still benefit from our consultants’ considerable knowledge and experience. <a href=\"https://cognitas.msonet.co.uk/contact/\"><u>Get in touch</u></a> to talk through your options.'),
(30863, 816, '_full_width_components_0_two_column_content_0_text', 'field_5ed8f3421c225'),
(30864, 816, 'full_width_components_0_two_column_content_0_read_more_link', ''),
