(31744, 825, 'full_width_components_6_two_column_content_0_column_style', 'image-right'),
(31745, 825, '_full_width_components_6_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(31746, 825, 'full_width_components_6_two_column_content_0_title', ''),
(31747, 825, '_full_width_components_6_two_column_content_0_title', 'field_5ed8f3421c210'),
(31748, 825, 'full_width_components_6_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
