(31885, 828, '_components_0_timeline_items_4_timeline_content', 'field_5ebd023fd7bfe'),
(31886, 828, 'components_0_timeline_items', '5'),
(31887, 828, '_components_0_timeline_items', 'field_5ebd0548c3669_field_5ebd0228d7bfc'),
(31888, 828, 'full_width_components_0_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(31889, 828, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(31890, 828, 'full_width_components_0_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(31891, 828, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(31892, 828, 'full_width_components_0_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n&nbsp;\r\n\r\n<img class=\"alignnone wp-image-826 size-full\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/06/Immersive-process-1.png\" alt=\"\" width=\"6668\" height=\"2361\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
