(2104, 'GTranslate', 'a:22:{s:11:\"pro_version\";s:0:\"\";s:18:\"enterprise_version\";s:0:\"\";s:15:\"url_translation\";s:0:\"\";s:17:\"add_hreflang_tags\";s:0:\"\";s:17:\"email_translation\";s:0:\"\";s:10:\"new_window\";s:0:\"\";s:12:\"show_in_menu\";s:0:\"\";s:26:\"floating_language_selector\";s:2:\"no\";s:21:\"native_language_names\";s:0:\"\";s:9:\"analytics\";s:0:\"\";s:23:\"detect_browser_language\";s:0:\"\";s:12:\"add_new_line\";i:1;s:16:\"default_language\";s:2:\"en\";s:18:\"translation_method\";s:5:\"onfly\";s:11:\"widget_look\";s:19:\"dropdown_with_flags\";s:9:\"flag_size\";i:24;s:11:\"widget_code\";s:35922:\"<!-- GTranslate: https://gtranslate.io/ -->\r\n<style type=\"text/css\">\r\n.switcher {font-family:Arial;font-size:10pt;text-align:left;cursor:pointer;overflow:hidden;width:163px;line-height:17px;}\r\n.switcher a {text-decoration:none;display:block;font-size:10pt;-webkit-box-sizing:content-box;-moz-box-sizing:content-box;box-sizing:content-box;}\r\n.switcher a img {vertical-align:middle;display:inline;border:0;padding:0;margin:0;opacity:0.8;}\r\n.switcher a:hover img {opacity:1;}\r\n.switcher .selected {background:#FFFFFF url(//cognitas.msonet.co.uk/wp-content/plugins/gtranslate/switcher.png) repeat-x;position:relative;z-index:9999;}\r\n.switcher .selected a {border:1px solid #CCCCCC;background:url(//cognitas.msonet.co.uk/wp-content/plugins/gtranslate/arrow_down.png) 146px center no-repeat;color:#666666;padding:3px 5px;width:151px;}\r\n.switcher .selected a.open {background-image:url(//cognitas.msonet.co.uk/wp-content/plugins/gtranslate/arrow_up.png)}\r\n.switcher .selected a:hover {background:#F0F0F0 url(//cognitas.msonet.co.uk/wp-content/plugins/gtranslate/arrow_down.png) 146px center no-repeat;}\r\n.switcher .option {position:relative;z-index:9998;border-left:1px solid #CCCCCC;border-right:1px solid #CCCCCC;border-bottom:1px solid #CCCCCC;background-color:#EEEEEE;display:none;width:161px;max-height:198px;-webkit-box-sizing:content-box;-moz-box-sizin