INSERT INTO `wpcu_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(805, 273, '_full_width_components_1_tabbed_content', 'field_5eaaa9e6b2cfb_field_5eaaa91f84c57'),
(806, 273, 'full_width_components_1_video', ''),
(807, 273, '_full_width_components_1_video', 'field_5eaaa9e6b2cfb_field_5eaaa98d84c5b'),
(808, 273, 'full_width_components_1_button', ''),
(809, 273, '_full_width_components_1_button', 'field_5eaaa9e6b2cfb_field_5eaaa9ac84c5c'),
(810, 5, 'full_width_components_1_tabbed_content_1_tab_title', 'Connect'),
(811, 5, '_full_width_components_1_tabbed_content_1_tab_title', 'field_5eaaa92b84c58'),
(812, 5, 'full_width_components_1_tabbed_content_1_tab_content', 'With the potential to engage learners around the world, the platform is a powerful tool for collaborative working. It brings people and teams with different skill sets together to experience and gain insights from the unique perspectives of others. <br><br>Facilitators have real-time visibility of participants’ progress during the training enabling agile, responsive facilitation with a consistent focus on the knowledge gaps that need to be addressed. This significantly reduces training time and ensures value for money. '),
(813, 5, '_full_width_components_1_tabbed_content_1_tab_content', 'field_5eaaa93b84c59'),
(814, 5, 'full_width_components_1_tabbed_content_1_read_more_link', ''),
(815, 5, '_full_width_components_1_tabbed_content_1_read_more_link', 'field_5eaaa95784c5a'),
(816, 5, 'full_width_components_1_tabbed_content_2_tab_title', 'Measure'),
(817, 5, '_full_width_components_1_tabbed_content_2_tab_title', 'field_5eaaa92b84c58'),
(818, 5, 'full_width_components_1_tabbed_content_2_tab_content', 'View360 Global™ is an approved group learning tool that also allows you to assess  and analyse the performance of individuals.  <br><br>  You can monitor participants’ responses in real-time and, after the event, you will receive a comprehensive record of activity. This provides clear evidence that outcomes have been met – an essential requirement if the training is part of an accredited learning process. <br><br>'),
(819, 5, '_full_width_components_1_tabbed_content_2_tab_content', 'field_5eaaa93b84c59'),
