(2994, 339, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(2995, 339, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(2996, 339, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas our highly qualified and motivated executive team are all  experts in their field, with an ideal  combination of extensive learning  and development experience,  complimented by many years of  operational expertise. This blend  enables us to deliver technical and training from junior to  strategic levels.'),
(2997, 339, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
