(3406, 350, 'full_width_components_6_alternating_image_text_0_image', '334'),
(3407, 350, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(3408, 350, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(3409, 350, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(3410, 350, 'full_width_components_6_alternating_image_text_1_text', 'Our philosophy prompts a paradigm shift in education, learning & development for the private and public sectors by offering cost effective and sustainable learning solutions. Our business is based on transparent and strong moral and ethical values that have been nurtured through the  delivery of training and technical  assistance by our parent company in 54 countries.'),
(3411, 350, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(3412, 350, 'full_width_components_6_alternating_image_text_1_read_more_link', ''),
