(3621, 351, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(3622, 351, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(3623, 351, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(3624, 351, 'full_width_components_6_alternating_image_text_2_text', 'View360 Global™ Platform has  already been extensively employed in a number of government and industry contracts in 14 countries. This is an exciting time at Cognitas as we explore the vast potential of View360 with clients including The UK National Crime agency, Council of Europe, City of London Police, the Government of the United Arab Emirates and the Isle of Man Ship Registry.'),
(3625, 351, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
