(3833, 360, '_full_width_components_5_call_to_actions', 'field_5eabdc9f59951_field_5eabdeb53131f'),
(3834, 360, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(3835, 360, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(3836, 360, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas our highly qualified and motivated executive team are all  experts in their field, with an ideal  combination of extensive learning  and development experience,  complimented by many years of  operational expertise. This blend  enables us to deliver technical and training from junior to  strategic levels.'),
(3837, 360, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(3838, 360, 'full_width_components_6_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:10:\"Components\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(3839, 360, '_full_width_components_6_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(3840, 360, 'full_width_components_6_alternating_image_text_0_image', '334'),
(3841, 360, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(3842, 360, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(3843, 360, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(3844, 360, 'full_width_components_6_alternating_image_text_1_text', 'Our philosophy prompts a paradigm shift in education, learning & development for the private and public sectors by offering cost effective and sustainable learning solutions. Our business is based on transparent and strong moral and ethical values that have been nurtured through the  delivery of training and technical  assistance by our parent company in 54 countries.'),
(3845, 360, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(3846, 360, 'full_width_components_6_alternating_image_text_1_read_more_link', ''),
(3847, 360, '_full_width_components_6_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(3848, 360, 'full_width_components_6_alternating_image_text_1_image', '335'),
(3849, 360, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(3850, 360, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(3851, 360, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(3852, 360, 'full_width_components_6_alternating_image_text_2_text', 'View360 Global™ Platform has  already been extensively employed in a number of government and industry contracts in 14 countries. This is an exciting time at Cognitas as we explore the vast potential of View360 with clients including The UK National Crime agency, Council of Europe, City of London Police, the Government of the United Arab Emirates and the Isle of Man Ship Registry.'),
(3853, 360, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(3854, 360, 'full_width_components_6_alternating_image_text_2_read_more_link', ''),
