(4120, 376, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(4121, 376, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(4122, 376, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas our highly qualified and motivated executive team are all  experts in their field, with an ideal  combination of extensive learning  and development experience,  complimented by many years of  operational expertise. This blend  enables us to deliver technical and training from junior to  strategic levels.'),
(4123, 376, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(4124, 376, 'full_width_components_6_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:10:\"Components\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(4125, 376, '_full_width_components_6_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(4126, 376, 'full_width_components_6_alternating_image_text_0_image', '334'),
(4127, 376, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(4128, 376, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(4129, 376, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(4130, 376, 'full_width_components_6_alternating_image_text_1_text', 'Our philosophy prompts a paradigm shift in education, learning & development for the private and public sectors by offering cost effective and sustainable learning solutions. Our business is based on transparent and strong moral and ethical values that have been nurtured through the  delivery of training and technical  assistance by our parent company in 54 countries.'),
(4131, 376, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(4132, 376, 'full_width_components_6_alternating_image_text_1_read_more_link', ''),
