(5645, 213, '_components_7_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(5646, 213, 'components_7_timeline_items_0_timeline_content', 'The process begins with gap analysis to help us identify your specific requirements and the most cost-effective solution.'),
(5647, 213, '_components_7_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(5648, 213, 'components_7_timeline_items_1_timeline_title', 'Advice'),
(5649, 213, '_components_7_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(5650, 213, 'components_7_timeline_items_1_timeline_content', 'Based on your anticipated annual training schedule, we’ll recommend the most suitable licence.'),
(5651, 213, '_components_7_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(5652, 213, 'components_7_timeline_items_2_timeline_title', 'Management'),
(5653, 213, '_components_7_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(5654, 213, 'components_7_timeline_items_2_timeline_content', 'You’ll have access to your own account management system through the client access area on our website.'),
(5655, 213, '_components_7_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(5656, 213, 'components_7_timeline_items_3_timeline_title', 'Training'),
(5657, 213, '_components_7_timeline_items_3_timeline_title', 'field_5ebd0237d7bfd'),
(5658, 213, 'components_7_timeline_items_3_timeline_content', 'An onsite training course on scenario building, media development, and how to use the platform is included in the licence price.'),
(5659, 213, '_components_7_timeline_items_3_timeline_content', 'field_5ebd023fd7bfe'),
(5660, 213, 'components_7_timeline_items_4_timeline_title', 'Support'),
(5661, 213, '_components_7_timeline_items_4_timeline_title', 'field_5ebd0237d7bfd'),
(5662, 213, 'components_7_timeline_items_4_timeline_content', 'Enjoy the reassurance of technical support, upgrades and additional training.'),
(5663, 213, '_components_7_timeline_items_4_timeline_content', 'field_5ebd023fd7bfe'),
