(6341, 452, '_full_width_components_1_button', 'field_5eaaa9e6b2cfb_field_5eaaa9ac84c5c'),
(6342, 452, 'full_width_components_1_tabbed_content_1_tab_title', 'Create'),
(6343, 452, '_full_width_components_1_tabbed_content_1_tab_title', 'field_5eaaa92b84c58'),
(6344, 452, 'full_width_components_1_tabbed_content_1_tab_content', 'With the potential to engage learners around the world, the platform is a powerful tool for collaborative working. It brings people and teams with different skill sets together to experience and gain insights from the unique perspectives of others. <br<<br>Facilitators have real-time visibility of participants’ progress during the training enabling agile, responsive facilitation with a consistent focus on the knowledge gaps that need to be addressed. This significantly reduces training time and ensures value for money. '),
(6345, 452, '_full_width_components_1_tabbed_content_1_tab_content', 'field_5eaaa93b84c59'),
