(6528, 454, 'full_width_components_1_image', '279'),
(6529, 454, '_full_width_components_1_image', 'field_5eaaa9e6b2cfb_field_5eaaa88084c4f'),
(6530, 454, 'full_width_components_1_title', 'About our learning platform'),
(6531, 454, '_full_width_components_1_title', 'field_5eaaa9e6b2cfb_field_5eaaa8a084c50'),
(6532, 454, 'full_width_components_1_subtitle', 'If you need to test and develop decision making skills, our versatile View360 Global™ platform allows you to create an immersive online learning environment tailored to meet your specific needs.  <br><br> Here are just some of the areas where our clients have discovered its advantages:'),
(6533, 454, '_full_width_components_1_subtitle', 'field_5eaaa9e6b2cfb_field_5eaaa8ad84c51'),
(6534, 454, 'full_width_components_1_left_side_bullet_points_0_bullet_point', 'Crisis management response'),
(6535, 454, '_full_width_components_1_left_side_bullet_points_0_bullet_point', 'field_5eaaa90784c56'),
(6536, 454, 'full_width_components_1_left_side_bullet_points_1_bullet_point', 'Compliance training'),
(6537, 454, '_full_width_components_1_left_side_bullet_points_1_bullet_point', 'field_5eaaa90784c56'),
(6538, 454, 'full_width_components_1_left_side_bullet_points_2_bullet_point', 'Business continuity planning'),
(6539, 454, '_full_width_components_1_left_side_bullet_points_2_bullet_point', 'field_5eaaa90784c56'),
(6540, 454, 'full_width_components_1_left_side_bullet_points', '3'),
(6541, 454, '_full_width_components_1_left_side_bullet_points', 'field_5eaaa9e6b2cfb_field_5eaaa8b384c52'),
(6542, 454, 'full_width_components_1_right_side_bullet_points_0_bullet_point', 'Safeguarding and education'),
(6543, 454, '_full_width_components_1_right_side_bullet_points_0_bullet_point', 'field_5eaaa8fe84c55'),
(6544, 454, 'full_width_components_1_right_side_bullet_points_1_bullet_point', 'Testing policy, procedures and gap analysis'),
(6545, 454, '_full_width_components_1_right_side_bullet_points_1_bullet_point', 'field_5eaaa8fe84c55'),
(6546, 454, 'full_width_components_1_right_side_bullet_points_2_bullet_point', 'Criminal Justice Sector training  '),
(6547, 454, '_full_width_components_1_right_side_bullet_points_2_bullet_point', 'field_5eaaa8fe84c55'),
(6548, 454, 'full_width_components_1_right_side_bullet_points', '3'),
(6549, 454, '_full_width_components_1_right_side_bullet_points', 'field_5eaaa9e6b2cfb_field_5eaaa8f384c54'),
(6550, 454, 'full_width_components_1_tabbed_content_0_tab_title', 'Simplify'),
(6551, 454, '_full_width_components_1_tabbed_content_0_tab_title', 'field_5eaaa92b84c58'),
(6552, 454, 'full_width_components_1_tabbed_content_0_tab_content', 'View360 Global™ training can be delivered in the workplace or remotely, with participants in multiple locations. No complex IT infrastructure is required – it works on any computer using Chrome or Firefox. And because the platform is multilingual, everyone can participate in their own language. <br><br>  It’s also easy to use, which means minimal training time is required to ensure facilitators and participants are up to speed. Where internet access is unavailable, we also offer a LAN version.'),
(6553, 454, '_full_width_components_1_tabbed_content_0_tab_content', 'field_5eaaa93b84c59'),
(6554, 454, 'full_width_components_1_tabbed_content_0_read_more_link', ''),
(6555, 454, '_full_width_components_1_tabbed_content_0_read_more_link', 'field_5eaaa95784c5a'),
(6556, 454, 'full_width_components_1_tabbed_content', '4'),
(6557, 454, '_full_width_components_1_tabbed_content', 'field_5eaaa9e6b2cfb_field_5eaaa91f84c57'),
(6558, 454, 'full_width_components_1_video', 'https://player.vimeo.com/external/171376270.hd.mp4?s=a31cb6b2714f07a9423cab5080233284b56d0d34&profile_id=119'),
(6559, 454, '_full_width_components_1_video', 'field_5eaaa9e6b2cfb_field_5eaaa98d84c5b'),
(6560, 454, 'full_width_components_1_button', 'a:3:{s:5:\"title\";s:20:\"Book a Demonstration\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(6561, 454, '_full_width_components_1_button', 'field_5eaaa9e6b2cfb_field_5eaaa9ac84c5c'),
(6562, 454, 'full_width_components_1_tabbed_content_1_tab_title', 'Connect'),
(6563, 454, '_full_width_components_1_tabbed_content_1_tab_title', 'field_5eaaa92b84c58'),
(6564, 454, 'full_width_components_1_tabbed_content_1_tab_content', 'With the potential to engage learners around the world, the platform is a powerful tool for collaborative working. It brings people and teams with different skill sets together to experience and gain insights from the unique perspectives of others. <br><br>Facilitators have real-time visibility of participants’ progress during the training enabling agile, responsive facilitation with a consistent focus on the knowledge gaps that need to be addressed. This significantly reduces training time and ensures value for money. '),
(6565, 454, '_full_width_components_1_tabbed_content_1_tab_content', 'field_5eaaa93b84c59'),
(6566, 454, 'full_width_components_1_tabbed_content_1_read_more_link', ''),
(6567, 454, '_full_width_components_1_tabbed_content_1_read_more_link', 'field_5eaaa95784c5a'),
(6568, 454, 'full_width_components_1_tabbed_content_2_tab_title', 'Measure'),
(6569, 454, '_full_width_components_1_tabbed_content_2_tab_title', 'field_5eaaa92b84c58'),
(6570, 454, 'full_width_components_1_tabbed_content_2_tab_content', 'View360 Global™ is an approved group learning tool that also allows you to assess  and analyse the performance of individuals.  <br><br>  You can monitor participants’ responses in real-time and, after the event, you will receive a comprehensive record of activity. This provides clear evidence that outcomes have been met – an essential requirement if the training is part of an accredited learning process. <br><br>'),
(6571, 454, '_full_width_components_1_tabbed_content_2_tab_content', 'field_5eaaa93b84c59'),
(6572, 454, 'full_width_components_1_tabbed_content_2_read_more_link', 'a:3:{s:5:\"title\";s:35:\" More about measurable results &gt;\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
