(6717, 455, '_summary_image', 'field_5ea83004efb2d'),
(6718, 455, 'full_width_components_0_component_title', 'Does the competency of teams or individuals rely on the quality of the training or learning that you provide? '),
(6719, 455, '_full_width_components_0_component_title', 'field_5e3bd2cd0eec0_field_5ea9847fcbc59'),
(6720, 455, 'full_width_components_0_component_subtitle', 'The View360 Global™ platform allows you to create bespoke learning solutions, in over 90 languages, with the full support of our expert team. '),
(6721, 455, '_full_width_components_0_component_subtitle', 'field_5e3bd2cd0eec0_field_5ea98490cbc5a'),
(6722, 455, 'full_width_components_0_icons', '5'),
