(7117, 456, '_full_width_components_8_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(7118, 456, 'full_width_components_8_testimonials_0_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements.'),
(7119, 456, '_full_width_components_8_testimonials_0_text', 'field_5cac5d7b5b816'),
(7120, 456, 'full_width_components_8_testimonials_0_author', 'Happy View360 Global™ user'),
