(7299, 460, '_full_width_components_5_call_to_actions', 'field_5eabdc9f59951_field_5eabdeb53131f'),
(7300, 460, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(7301, 460, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(7302, 460, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas our highly qualified and motivated executive team are all  experts in their field, with an ideal  combination of extensive learning  and development experience,  complimented by many years of  operational expertise. This blend  enables us to deliver technical and training from junior to  strategic levels.'),
(7303, 460, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(7304, 460, 'full_width_components_6_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:10:\"Components\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(7305, 460, '_full_width_components_6_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(7306, 460, 'full_width_components_6_alternating_image_text_0_image', '334'),
(7307, 460, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(7308, 460, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(7309, 460, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(7310, 460, 'full_width_components_6_alternating_image_text_1_text', 'Our philosophy prompts a paradigm shift in education, learning & development for the private and public sectors by offering cost effective and sustainable learning solutions. Our business is based on transparent and strong moral and ethical values that have been nurtured through the  delivery of training and technical  assistance by our parent company in 54 countries.'),
(7311, 460, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(7312, 460, 'full_width_components_6_alternating_image_text_1_read_more_link', ''),
(7313, 460, '_full_width_components_6_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(7314, 460, 'full_width_components_6_alternating_image_text_1_image', '335'),
(7315, 460, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(7316, 460, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(7317, 460, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(7318, 460, 'full_width_components_6_alternating_image_text_2_text', 'View360 Global™ Platform has  already been extensively employed in a number of government and industry contracts in 14 countries. This is an exciting time at Cognitas as we explore the vast potential of View360 with clients including The UK National Crime agency, Council of Europe, City of London Police, the Government of the United Arab Emirates and the Isle of Man Ship Registry.'),
(7319, 460, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(7320, 460, 'full_width_components_6_alternating_image_text_2_read_more_link', ''),
