(7518, 461, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(7519, 461, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(7520, 461, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(7521, 461, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(7522, 461, 'full_width_components_6_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:10:\"Components\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(7523, 461, '_full_width_components_6_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(7524, 461, 'full_width_components_6_alternating_image_text_0_image', '334'),
(7525, 461, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(7526, 461, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(7527, 461, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(7528, 461, 'full_width_components_6_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(7529, 461, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(7530, 461, 'full_width_components_6_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:25:\"More about our philosophy\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(7531, 461, '_full_width_components_6_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(7532, 461, 'full_width_components_6_alternating_image_text_1_image', '335'),
(7533, 461, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(7534, 461, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(7535, 461, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(7536, 461, 'full_width_components_6_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(7537, 461, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
