(7569, 461, '_full_width_components_8_button', 'field_5eac2de411183_field_5eac2edad830e'),
(7570, 461, 'full_width_components_1_tabbed_content_3_tab_title', 'Immerse'),
(7571, 461, '_full_width_components_1_tabbed_content_3_tab_title', 'field_5eaaa92b84c58'),
(7572, 461, 'full_width_components_1_tabbed_content_3_tab_content', 'Our platform allows you to customise training programmes using mixed media to help recreate real-life situations. Meaningful and relevant for those taking part, it engages in ways that conventional and non-blended learning can’t. <br><br>   Participants work in small groups or as individuals and can communicate directly with the facilitator in their native language. This safe learning environment allows knowledge to be assimilated in less time, improves retention and has been proved to increase productivity. <br><br>'),
(7573, 461, '_full_width_components_1_tabbed_content_3_tab_content', 'field_5eaaa93b84c59'),
