(8486, 487, '_full_width_components_4_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(8487, 487, 'full_width_components_5_component_title', 'Our Training Credientals'),
(8488, 487, '_full_width_components_5_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(8489, 487, 'full_width_components_5_component_subtitle', ''),
(8490, 487, '_full_width_components_5_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(8491, 487, 'full_width_components_5_content', 'Skills for Justice (SFJ) Awards is an awarding organisation approved by the Qualification Regulators to provide qualifications in England, Wales and Northern Ireland.\r\n\r\nWe were awarded SFJ Centre Approval Status in November 2019 this allows our company to design and deliver accredited training globally under their Accredited Learning professionally (ALP) scheme.\r\n\r\nBy working with SFJ Awards, we can develop and implement accredited and certificated learning programmes that adhere to a recognised quality assurance process.\r\n\r\nThis results in a quality, collaborative, tailored training programme which allows our clients to have confidence in the learning product they create with us. It also ensures learners have the appropriate skills to do their jobs with proficiency.'),
(8492, 487, '_full_width_components_5_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(8493, 487, 'full_width_components_5_buttons_0_button', 'a:3:{s:5:\"title\";s:20:\"SFJ Awards Approved \";s:3:\"url\";s:22:\"https://sfjawards.com/\";s:6:\"target\";s:6:\"_blank\";}'),
