(8665, 491, 'full_width_components_0_alternating_image_text', '3'),
(8666, 491, '_full_width_components_0_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(8667, 491, 'full_width_components_1_component_title', 'Management Team'),
(8668, 491, '_full_width_components_1_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(8669, 491, 'full_width_components_1_alternating_image_text_0_title', 'James Robinson - Technical Director'),
(8670, 491, '_full_width_components_1_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(8671, 491, 'full_width_components_1_alternating_image_text_0_text', 'James has spent 13 years as a software architect and developer in the telecommunications and mobile apps industry. He has been a lead engineer in many deployments of software from mainframes to mobile phones. He now specialises in web frameworks and serverless infrastructure, having moved from corporate industry, to design agency, to now working independently as a freelance IT consultant. James has been working on the development of View360 Global since 2017 and was appointed the Technical Director of Cognitas in 2019.'),
(8672, 491, '_full_width_components_1_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
