(8727, 491, 'full_width_components_7_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care.'),
(8728, 491, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(8729, 491, 'full_width_components_7_component_subtitle', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.'),
(8730, 491, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
