(9315, 505, 'components_0_timeline_items_0_timeline_title', 'User FriendlyINSERT INTO `wpcu_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(9665, 510, '_full_width_components_0_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(9666, 510, 'full_width_components_0_alternating_image_text_1_title', 'Capturing learning activity'),
(9667, 510, '_full_width_components_0_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(9668, 510, 'full_width_components_0_alternating_image_text_1_text', 'View360 Global™ captures the  learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results. '),
(9669, 510, '_full_width_components_0_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(9670, 510, 'full_width_components_0_alternating_image_text_1_read_more_link', ''),
(9671, 510, '_full_width_components_0_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(9672, 510, 'full_width_components_0_alternating_image_text_1_image', '277'),
(9673, 510, '_full_width_components_0_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(9674, 510, 'full_width_components_0_alternating_image_text', '2'),
(9675, 510, '_full_width_components_0_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(9676, 510, 'full_width_components_1_component_title', 'Measuring the impact of your learning'),
(9677, 510, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(9678, 510, 'full_width_components_1_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(9679, 510, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(9680, 510, 'full_width_components_1_content', '<img class=\"alignnone wp-image-508 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.52.50-e1590749697636-1024x422.png\" alt=\"\" width=\"1024\" height=\"422\" />\r\n<h4>Assessing return on expectations (ROE)</h4>\r\nA successful training initiative delivers a return on expectations to its key business stakeholders. It’s a practitioner approach to creating and demonstrating the organisational value of training – and shows clearly the degree to which expectations have been satisfied.\r\n\r\n<b>We use the established New World Kirkpatrick model to measure your ROE.</b>\r\n\r\nThis is one of a number of proven methodologies that we employ for the measurement of data as part of our <u>consultancy services</u>.\r\n\r\nAs certified Kirkpatrick model practitioners we can provide:\r\n<ul>\r\n 	<li>A full analysis of the training you’ve delivered</li>\r\n 	<li>Evidence of achieving outcomes and objectives</li>\r\n 	<li>Recommendations for continued professional development.</li>\r\n</ul>\r\n&nbsp;'),
(9681, 510, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(9682, 510, 'full_width_components_1_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
