(9828, 514, 'show_left_sidebar', '0'),
(9829, 514, '_show_left_sidebar', 'field_5e38357452128'),
(9830, 514, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n&nbsp;\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(9831, 514, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(9832, 514, 'full_width_components_0_component_title', ''),
(9833, 514, '_full_width_components_0_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(9834, 514, 'full_width_components_0_alternating_image_text_0_title', 'Providing Proof'),
(9835, 514, '_full_width_components_0_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(9836, 514, 'full_width_components_0_alternating_image_text_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(9837, 514, '_full_width_components_0_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(9838, 514, 'full_width_components_0_alternating_image_text_0_read_more_link', ''),
