(9967, 518, 'show_left_sidebar', '0'),
(9968, 518, '_show_left_sidebar', 'field_5e38357452128'),
(9969, 518, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(9970, 518, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(9971, 518, 'full_width_components_0_component_title', ''),
(9972, 518, '_full_width_components_0_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(9973, 518, 'full_width_components_0_alternating_image_text_0_title', 'Providing Proof'),
(9974, 518, '_full_width_components_0_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(9975, 518, 'full_width_components_0_alternating_image_text_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(9976, 518, '_full_width_components_0_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(9977, 518, 'full_width_components_0_alternating_image_text_0_read_more_link', ''),
(9978, 518, '_full_width_components_0_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(9979, 518, 'full_width_components_0_alternating_image_text_0_image', '310'),
(9980, 518, '_full_width_components_0_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(9981, 518, 'full_width_components_0_alternating_image_text_1_title', 'Capturing learning activity'),
(9982, 518, '_full_width_components_0_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(9983, 518, 'full_width_components_0_alternating_image_text_1_text', 'View360 Global™ captures the  learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results. '),
(9984, 518, '_full_width_components_0_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(9985, 518, 'full_width_components_0_alternating_image_text_1_read_more_link', ''),
(9986, 518, '_full_width_components_0_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(9987, 518, 'full_width_components_0_alternating_image_text_1_image', '277'),
(9988, 518, '_full_width_components_0_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(9989, 518, 'full_width_components_0_alternating_image_text', '2'),
(9990, 518, '_full_width_components_0_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(9991, 518, 'full_width_components_1_component_title', 'Measuring the impact of your learning'),
(9992, 518, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(9993, 518, 'full_width_components_1_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(9994, 518, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(9995, 518, 'full_width_components_1_content', '<img class=\"alignnone wp-image-508 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.52.50-e1590749697636-1024x422.png\" alt=\"\" width=\"1024\" height=\"422\" />\r\n<h1>Assessing return on expectations (ROE)</h1>\r\nA successful training initiative delivers a return on expectations to its key business stakeholders. It’s a practitioner approach to creating and demonstrating the organisational value of training – and shows clearly the degree to which expectations have been satisfied.\r\n\r\n<b>We use the established New World Kirkpatrick model to measure your ROE.</b>\r\n\r\nThis is one of a number of proven methodologies that we employ for the measurement of data as part of our <u>consultancy services</u>.\r\n\r\nAs certified Kirkpatrick model practitioners we can provide:\r\n<ul>\r\n 	<li>A full analysis of the training you’ve delivered</li>\r\n 	<li>Evidence of achieving outcomes and objectives</li>\r\n 	<li>Recommendations for continued professional development.</li>\r\n</ul>\r\n<img class=\"alignnone wp-image-516 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-12.02.35-e1590750284396-1024x532.png\" alt=\"\" width=\"1024\" height=\"532\" />'),
(9996, 518, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
