(10319, 524, 'full_width_components_2_alternating_image_text_0_title', 'How We Assisted'),
(10320, 524, '_full_width_components_2_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(10321, 524, 'full_width_components_2_alternating_image_text_0_text', 'Collaborating closely with EXPOL and their established clients, we co designed and delivered a series of independent and well attended blended learning training events, where the immersive scenarios and media content were specifically designed to meet the operational needs of the diverse beneficiary organisations'),
(10322, 524, '_full_width_components_2_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(10323, 524, 'full_width_components_2_alternating_image_text_0_read_more_link', ''),
