(10326, 524, '_full_width_components_2_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(10327, 524, 'full_width_components_2_alternating_image_text_1_title', 'What was Achieved'),
(10328, 524, '_full_width_components_2_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(10329, 524, 'full_width_components_2_alternating_image_text_1_text', 'By delivering meaningful training using View360 Global for EXPOL’s clients we were able to provide them with a style of training that had not been experienced before by the participants. The consolidated experiential learning achieved and enjoyed by the participants evidenced value for money returned repeat business for EXPOL who continue to use the platform in their training programs'),
(10330, 524, '_full_width_components_2_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
