(10537, 525, '_full_width_components_8_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(10538, 525, 'full_width_components_8_testimonials_0_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements.'),
(10539, 525, '_full_width_components_8_testimonials_0_text', 'field_5cac5d7b5b816'),
(10540, 525, 'full_width_components_8_testimonials_0_author', 'Happy View360 Global™ user'),
(10541, 525, '_full_width_components_8_testimonials_0_author', 'field_5eac2ec641dad'),
(10542, 525, 'full_width_components_8_testimonials_1_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements. View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation.\r\n '),
(10543, 525, '_full_width_components_8_testimonials_1_text', 'field_5cac5d7b5b816'),
