(10617, 526, '_full_width_components_1_right_side_bullet_points_0_bullet_point', 'field_5eaaa8fe84c55'),
(10618, 526, 'full_width_components_1_right_side_bullet_points_1_bullet_point', 'Testing policy, procedures and gap analysis'),
