(10791, 527, '_full_width_components_0_component_title', 'field_5e3bd2cd0eec0_field_5ea9847fcbc59'),
(10792, 527, 'full_width_components_0_component_subtitle', 'The View360 Global™ platform allows you to create bespoke learning solutions, in over 90 languages, with the full support of our expert team. '),
