(10965, 527, '_full_width_components_7_component_summary', 'field_5eafdf8b57587_field_5eafdf52d63fc'),
(10966, 527, 'full_width_components_7_case_studies', 'a:3:{i:0;s:3:\"364\";i:1;s:3:\"371\";i:2;s:3:\"369\";}'),
(10967, 527, '_full_width_components_7_case_studies', 'field_5eafdf8b57587_field_5eafdf4326db2'),
(10968, 527, 'full_width_components_8_component_title', 'What our clients say...'),
(10969, 527, '_full_width_components_8_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(10970, 527, 'full_width_components_8_testimonials_0_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements.'),
(10971, 527, '_full_width_components_8_testimonials_0_text', 'field_5cac5d7b5b816'),
(10972, 527, 'full_width_components_8_testimonials_0_author', 'Happy View360 Global™ user'),
(10973, 527, '_full_width_components_8_testimonials_0_author', 'field_5eac2ec641dad'),
(10974, 527, 'full_width_components_8_testimonials_1_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements. View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation.\r\n '),
(10975, 527, '_full_width_components_8_testimonials_1_text', 'field_5cac5d7b5b816'),
(10976, 527, 'full_width_components_8_testimonials_1_author', 'Happy View360 Global™ user'),
