(12064, 567, 'show_left_sidebar', '0'),
(12065, 567, '_show_left_sidebar', 'field_5e38357452128'),
(12066, 567, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(12067, 567, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(12068, 567, 'full_width_components_0_component_title', 'Multilingual Data Capture'),
(12069, 567, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(12070, 567, 'full_width_components_0_component_subtitle', 'Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth. '),
(12071, 567, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(12072, 567, 'full_width_components_0_content', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and\r\nafterwards, the record of activity provides clear evidence that desired outcomes have been met'),
(12073, 567, '_full_width_components_0_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(12074, 567, 'full_width_components_0_buttons', ''),
(12075, 567, '_full_width_components_0_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(12076, 567, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(12077, 567, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(12078, 567, 'full_width_components_1_two_column_content_0_title', ''),
(12079, 567, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(12080, 567, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(12081, 567, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(12082, 567, 'full_width_components_1_two_column_content_0_read_more_link', ''),
(12083, 567, '_full_width_components_1_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(12084, 567, 'full_width_components_1_two_column_content_0_image', '310'),
(12085, 567, '_full_width_components_1_two_column_content_0_image', 'field_5ed8f3421c23f'),
(12086, 567, 'full_width_components_1_two_column_content_1_column_style', 'image-right'),
(12087, 567, '_full_width_components_1_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(12088, 567, 'full_width_components_1_two_column_content_1_title', ''),
(12089, 567, '_full_width_components_1_two_column_content_1_title', 'field_5ed8f3421c210'),
(12090, 567, 'full_width_components_1_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
(12091, 567, '_full_width_components_1_two_column_content_1_text', 'field_5ed8f3421c225'),
(12092, 567, 'full_width_components_1_two_column_content_1_read_more_link', ''),
(12093, 567, '_full_width_components_1_two_column_content_1_read_more_link', 'field_5ed8f3421c235'),
(12094, 567, 'full_width_components_1_two_column_content_1_image', '277'),
(12095, 567, '_full_width_components_1_two_column_content_1_image', 'field_5ed8f3421c23f'),
(12096, 567, 'full_width_components_1_two_column_content', '2'),
(12097, 567, '_full_width_components_1_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(12098, 567, 'full_width_components_2_component_title', 'Measuring the impact of your learning'),
(12099, 567, '_full_width_components_2_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(12100, 567, 'full_width_components_2_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(12101, 567, '_full_width_components_2_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(12102, 567, 'full_width_components_2_content', '<img class=\"alignnone size-large wp-image-508\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.52.50-e1590749697636-1024x422.png\" alt=\"\" width=\"1024\" height=\"422\" />'),
(12103, 567, '_full_width_components_2_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(12104, 567, 'full_width_components_2_buttons', ''),
(12105, 567, '_full_width_components_2_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(12106, 567, 'full_width_components_3_text', ''),
(12107, 567, '_full_width_components_3_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(12108, 567, 'full_width_components_3_text_position', 'right'),
(12109, 567, '_full_width_components_3_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(12110, 567, 'full_width_components_3_background_image', '458'),
(12111, 567, '_full_width_components_3_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(12112, 567, 'full_width_components_4_component_title', 'Assessing return on expectations (ROE)'),
(12113, 567, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(12114, 567, 'full_width_components_4_component_subtitle', 'A successful training initiative delivers a return on expectations to its key business stakeholders.'),
(12115, 567, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(12116, 567, 'full_width_components_4_content', 'It’s a practitioner approach to creating and demonstrating the organisational value of training – and shows clearly the degree to which expectations have been satisfied.\r\n\r\n<b>We use the established New World Kirkpatrick model to measure your ROE.</b>\r\n\r\nThis is one of a number of proven methodologies that we employ for the measurement of data as part of our <u>consultancy services</u>.\r\n\r\nAs certified Kirkpatrick model practitioners we can provide:\r\n<ul>\r\n 	<li>A full analysis of the training you’ve delivered</li>\r\n 	<li>Evidence of achieving outcomes and objectives</li>\r\n 	<li>Recommendations for continued professional development.</li>\r\n</ul>\r\n<img class=\"alignnone wp-image-516 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-12.02.35-e1590750284396-1024x532.png\" alt=\"\" width=\"1024\" height=\"532\" />'),
(12117, 567, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(12118, 567, 'full_width_components_4_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(12119, 567, '_full_width_components_4_buttons_0_button', 'field_5eabf7d5bf1a9'),
(12120, 567, 'full_width_components_4_buttons_1_button', 'a:3:{s:5:\"title\";s:18:\"Kirkpatrick model \";s:3:\"url\";s:72:\"https://www.kirkpatrickpartners.com/Our-Philosophy/The-Kirkpatrick-Model\";s:6:\"target\";s:0:\"\";}'),
