(13819, 585, 'full_width_components_2_two_column_content_1_title', 'What was Achieved'),
(13820, 585, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(13821, 585, 'full_width_components_2_two_column_content_1_text', 'By delivering meaningful training using View360 Global for EXPOL’s clients we were able to provide them with a style of training that had not been experienced before by the participants. The consolidated experiential learning achieved and enjoyed by the participants evidenced value for money returned repeat business for EXPOL who continue to use the platform in their training programs'),
(13822, 585, '_full_width_components_2_two_column_content_1_text', 'field_5ed8f3421c225'),
