(13843, 369, 'full_width_components_0_two_column_content_0_column_style', 'image-left'),
(13844, 369, '_full_width_components_0_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13845, 369, 'full_width_components_0_two_column_content_0_title', 'REGIONAL ANTI CORRUPTION INITIATIVE (RAI)'),
(13846, 369, '_full_width_components_0_two_column_content_0_title', 'field_5ed8f3421c210'),
(13847, 369, 'full_width_components_0_two_column_content_0_text', '<h1>The Challenge</h1>\r\nThe RAI has a responsibility to deliver technical assistance in the area of anti-corruption (AC) to its 9 South East European country members as part of its funded training programs\r\n\r\nThrough our parent company’s long affiliation with RAI, we were asked to design immersive anti corruption training events to be delivered for multinational participants in their own language at the RAI Annual Summer School for AC Practitioners (2019) and at two multi country workshops to be held in Albania and North Macedonia in late 2019'),
(13848, 369, '_full_width_components_0_two_column_content_0_text', 'field_5ed8f3421c225'),
(13849, 369, 'full_width_components_0_two_column_content_0_read_more_link', 'a:3:{s:5:\"title\";s:11:\"RAI Website\";s:3:\"url\";s:24:\"http://www.rai-see.org//\";s:6:\"target\";s:6:\"_blank\";}'),
(13850, 369, '_full_width_components_0_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(13851, 369, 'full_width_components_0_two_column_content_0_image', '586'),
(13852, 369, '_full_width_components_0_two_column_content_0_image', 'field_5ed8f3421c23f'),
(13853, 369, 'full_width_components_0_two_column_content', '1'),
(13854, 369, '_full_width_components_0_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
