(13943, 371, 'full_width_components_0_two_column_content_0_column_style', 'image-left'),
(13944, 371, '_full_width_components_0_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13945, 371, 'full_width_components_0_two_column_content_0_title', 'SMARTDESC Ltd'),
(13946, 371, '_full_width_components_0_two_column_content_0_title', 'field_5ed8f3421c210'),
(13947, 371, 'full_width_components_0_two_column_content_0_text', '<h1>The Challenge</h1>\r\nSmartdesc provide IT Strategy, Data Protection and Support services to the Not for Profit sector.\r\n\r\nSmartdesc had identified that a number of SME Charities were vulnerable to cyberattack and wished to co-host a pro bono educational training workshop where an immersive exercise would be delivered alongside a presentation from their IT experts in order to broaden the participants knowledge and awareness of IT Security best practices.'),
(13948, 371, '_full_width_components_0_two_column_content_0_text', 'field_5ed8f3421c225'),
(13949, 371, 'full_width_components_0_two_column_content_0_read_more_link', 'a:3:{s:5:\"title\";s:21:\"SMARTDESC Ltd Website\";s:3:\"url\";s:28:\"https://www.smartdesc.co.uk/\";s:6:\"target\";s:6:\"_blank\";}'),
(13950, 371, '_full_width_components_0_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(13951, 371, 'full_width_components_0_two_column_content_0_image', '588'),
(13952, 371, '_full_width_components_0_two_column_content_0_image', 'field_5ed8f3421c23f'),
(13953, 371, 'full_width_components_0_two_column_content', '1'),
(13954, 371, '_full_width_components_0_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(13955, 371, 'full_width_components_1_background_colour', 'blue'),
(13956, 371, '_full_width_components_1_background_colour', 'field_5eac2de411183_field_5ed9f972147ec'),
(13957, 371, 'full_width_components_1_component_title', ''),
(13958, 371, '_full_width_components_1_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(13959, 371, 'full_width_components_1_testimonials_0_text', '<br><br>\r\n“The Cognitas platform enabled us to simulate what a real ransomware attack might look and feel like; we could then challenge the delegates to make decisions that directly affected the outcome. This made the session feel very real, so the delegates were immersed in the training and got the maximum benefit from it. The feedback was outstanding”\r\n<br><br>'),
(13960, 371, '_full_width_components_1_testimonials_0_text', 'field_5cac5d7b5b816'),
(13961, 371, 'full_width_components_1_testimonials_0_author', 'James Field, Customer Strategy Director'),
