(13967, 371, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(13968, 371, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(13969, 371, 'full_width_components_2_two_column_content_0_title', 'How We Assisted'),
(13970, 371, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(13971, 371, 'full_width_components_2_two_column_content_0_text', 'We worked closely with Andrew Coyle, Head of Information Security, and James Field, Strategy Director at Smartdesc, to build a ransomware attack scenario that was designed to educate the participants around the threat, response and building preventative measures, policy and resilience.\r\n\r\nSome 21 representatives from SME charities attended the half day workshop where a 2-hour exercise was delivered followed by a presentation'),
(13972, 371, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(13973, 371, 'full_width_components_2_two_column_content_0_read_more_link', ''),
