(13978, 371, '_full_width_components_2_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(13979, 371, 'full_width_components_2_two_column_content_1_title', 'What was Achieved'),
(13980, 371, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(13981, 371, 'full_width_components_2_two_column_content_1_text', 'Delivering the exercise on the platform without any pre warning of what to expect highlighted a significant number of vulnerabilities in the sector where many of the SMEs did not have the resources or knowledge of larger companies to mitigate cyberthreats. The participants were universal in their praise for the benefits of the workshop and the technical advice offered by Smartdesc, indicating that they were intending to implement what assistance had been offered.'),
(13982, 371, '_full_width_components_2_two_column_content_1_text', 'field_5ed8f3421c225'),
