(14010, 589, '_full_width_components_1_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(14011, 589, 'full_width_components_1_testimonials_0_text', '<br><br>\r\n“The Cognitas platform enabled us to simulate what a real ransomware attack might look and feel like; we could then challenge the delegates to make decisions that directly affected the outcome. This made the session feel very real, so the delegates were immersed in the training and got the maximum benefit from it. The feedback was outstanding”\r\n<br><br>'),
(14012, 589, '_full_width_components_1_testimonials_0_text', 'field_5cac5d7b5b816'),
(14013, 589, 'full_width_components_1_testimonials_0_author', 'James Field, Customer Strategy Director'),
