(14640, 593, '_full_width_components_1_team_members', 'field_5eda47d03c7cb_field_5e662f17ae094'),
(14641, 593, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(14642, 593, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(14643, 593, 'full_width_components_2_two_column_content_0_title', ''),
(14644, 593, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(14645, 593, 'full_width_components_2_two_column_content_0_text', 'We’re a unique cadre of experienced practitioners with extensive experience\r\nof working in international jurisdictions, and across both the public and\r\nprivate sectors.\r\n\r\nWe bring a moral and ethical approach to the field of learning, with a deep\r\nappreciation of the complex challenges facing the different organisations we\r\nwork with. Remaining flexible and pragmatic in our advice and solutions,\r\nwe’re always prepared to adapt to the diverse environments in which we\r\noperate.\r\n\r\nOur solutions are practical and realistic, based on Learning and Development\r\nprinciples that make it easier for you to achieve your objectives. It’s a\r\nproven approach that means we consistently deliver meaningful and\r\nsustainable transformational change – combined with real value for money.'),
(14646, 593, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(14647, 593, 'full_width_components_2_two_column_content_0_read_more_link', ''),
