(14658, 593, '_full_width_components_3_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(14659, 593, 'full_width_components_4_component_title', 'Our Development'),
(14660, 593, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(14661, 593, 'full_width_components_4_component_subtitle', ''),
(14662, 593, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(14663, 593, 'full_width_components_4_content', 'Before Cognitas Global was founded in 2018, we built our experience on delivering capacity building, training and technical assistance in 54 countries through our parent company <u>AML Consulting (Global).</u>\r\n\r\nSince 2011, we’ve worked with numerous clients, including the UK Foreign &amp; Commonwealth Office, Department for International Development (DfID), UK National Crime Agency and National Economic Crime Centre, the United Nations Office for Drugs &amp; Crime (UNODC), and the Organisation for Security and Cooperation in Europe (OSCE).\r\n\r\nMeanwhile, our sister company AML Consulting (Global) UK has held SFJ Approved Training Centre status since 2017. It leads on the design and global delivery of Skills for Justice Awards accredited training programmes.'),
(14664, 593, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(14665, 593, 'full_width_components_4_buttons', ''),
