(14678, 593, '_full_width_components_7_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(14679, 593, 'full_width_components_8_component_title', ''),
(14680, 593, '_full_width_components_8_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(14681, 593, 'full_width_components_8_component_subtitle', ''),
(14682, 593, '_full_width_components_8_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(14683, 593, 'full_width_components_8_content', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care.\r\n\r\nCognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(14684, 593, '_full_width_components_8_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(14685, 593, 'full_width_components_8_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(14686, 593, '_full_width_components_8_buttons_0_button', 'field_5eabf7d5bf1a9'),
(14687, 593, 'full_width_components_8_buttons', '1'),
(14688, 593, '_full_width_components_8_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(14689, 593, 'full_width_components_6_two_column_content_0_column_style', 'image-left'),
(14690, 593, '_full_width_components_6_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(14691, 593, 'full_width_components_6_two_column_content_0_title', ''),
(14692, 593, '_full_width_components_6_two_column_content_0_title', 'field_5ed8f3421c210'),
(14693, 593, 'full_width_components_6_two_column_content_0_text', 'Skills for Justice (SFJ) Awards is an awarding organisation approved by the Qualification Regulators to provide qualifications in England, Wales and Northern Ireland. We were awarded SFJ Centre Approval Status in November 2019 this allows our company to design and deliver accredited training globally under their Accredited Learning professionally (ALP) scheme.\r\n\r\nBy working with SFJ Awards, we can develop and implement accredited and certificated learning programmes that adhere to a recognised quality assurance process.\r\n\r\nThis results in a quality, collaborative, tailored training programme which allows our clients to have confidence in the learning product they create with us. It also ensures learners have the appropriate skills to do their jobs with proficiency.'),
(14694, 593, '_full_width_components_6_two_column_content_0_text', 'field_5ed8f3421c225'),
(14695, 593, 'full_width_components_6_two_column_content_0_read_more_link', ''),
