(14850, 603, 'page_title_override', ''),
(14851, 603, '_page_title_override', 'field_5ea82fadefb2b'),
(14852, 603, 'page_summary', 'Delivering technical assistance worldwide & Working with the community'),
(14853, 603, '_page_summary', 'field_5ea82ff6efb2c'),
(14854, 603, 'summary_image', ''),
(14855, 603, '_summary_image', 'field_5ea83004efb2d'),
(14856, 603, 'components_0_content', '<p style=\"text-align: center;\">We’re a unique cadre of experienced practitioners with extensive experience of working in international jurisdictions, and across both the public and private sectors.</p>\r\n<p style=\"text-align: center;\">We bring a moral and ethical approach to the field of learning, with a deep appreciation of the complex challenges facing the different organisations we work with. Remaining flexible and pragmatic in our advice and solutions, we’re always prepared to adapt to the diverse environments in which we operate.</p>\r\n<p style=\"text-align: center;\">Our solutions are practical and realistic, based on Learning and Development principles that make it easier for you to achieve your objectives. It’s a proven approach that means we consistently deliver meaningful and sustainable transformational change – combined with real value for money.</p>\r\n&nbsp;'),
(14857, 603, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(14858, 603, 'full_width_components_0_component_title', 'Our Board'),
(14859, 603, '_full_width_components_0_component_title', 'field_5eda47d03c7cb_field_5eda4a06219d4'),
(14860, 603, 'full_width_components_0_team_members_0_name', 'Lawrie Day'),
(14861, 603, '_full_width_components_0_team_members_0_name', 'field_5e662f2fae095'),
(14862, 603, 'full_width_components_0_team_members_0_title', 'CEO'),
(14863, 603, '_full_width_components_0_team_members_0_title', 'field_5e6630f53495d'),
(14864, 603, 'full_width_components_0_team_members_0_background_image', '479'),
(14865, 603, '_full_width_components_0_team_members_0_background_image', 'field_5e662f3eae096'),
(14866, 603, 'full_width_components_0_team_members_0_content', 'Lawrie retired from the Metropolitan Police in 2010 as a Detective having served 30 years and latterly specialising in Financial Investigation and economic crime. He has worked in 35 countries as a Subject Matter Expert delivering technical assistance and training. As a qualified Learning &amp; Development practitioner, he has been designing and delivering anti money laundering, anti-corruption, intelligence development, financial investigation and asset recovery relating to national and transnational crime for the international aid organisations and foreign governments in addition to managing short to long term international projects . He is the designer of View360 Global and as the Director and CEO he now oversees the day to day operations of three Consulting companies.'),
(14867, 603, '_full_width_components_0_team_members_0_content', 'field_5e662f4cae097'),
(14868, 603, 'full_width_components_0_team_members_1_name', 'Colin Burrow '),
(14869, 603, '_full_width_components_0_team_members_1_name', 'field_5e662f2fae095'),
(14870, 603, 'full_width_components_0_team_members_1_title', 'Director'),
