(14955, 603, '_full_width_components_8_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(14956, 603, 'full_width_components_8_content', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care.\r\n\r\nCognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(14957, 603, '_full_width_components_8_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
