(15395, 607, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(15396, 607, 'full_width_components_4_component_subtitle', 'Our licencing plans and consultancy options'),
(15397, 607, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(15398, 607, 'full_width_components_4_content', 'The creation of your View360 Global™ learning solution is a collaborative process, with as much training, technical support and advice as you need from our experienced team.\r\n\r\nBy focusing on your specific operational requirements, budgets and timescales, we can help you choose the most cost-effective solution – be that a licencing plan or one of our consultancy services.'),
(15399, 607, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(15400, 607, 'full_width_components_4_buttons', ''),
