(15466, 607, 'full_width_components_8_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(15467, 607, '_full_width_components_8_button', 'field_5eac2de411183_field_5eac2edad830e'),
(15468, 607, 'full_width_components_1_tabbed_content_3_tab_title', 'Immerse'),
(15469, 607, '_full_width_components_1_tabbed_content_3_tab_title', 'field_5eaaa92b84c58'),
(15470, 607, 'full_width_components_1_tabbed_content_3_tab_content', 'Our platform allows you to customise training programmes using mixed media to help recreate real-life situations. Meaningful and relevant for those taking part, it engages in ways that conventional and non-blended learning can’t. <br><br>   Participants work in small groups or as individuals and can communicate directly with the facilitator in their native language. This safe learning environment allows knowledge to be assimilated in less time, improves retention and has been proved to increase productivity. <br><br>'),
(15471, 607, '_full_width_components_1_tabbed_content_3_tab_content', 'field_5eaaa93b84c59'),
(15472, 607, 'full_width_components_1_tabbed_content_3_read_more_link', 'a:3:{s:5:\"title\";s:35:\" More about immersive learning >  \";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(15473, 607, '_full_width_components_1_tabbed_content_3_read_more_link', 'field_5eaaa95784c5a'),
(15474, 607, 'full_width_components_1_text_under_bullets', 'We work with organisations from both the public and private sectors, including those following statutory or mandatory  training requirements.  <BR><BR> To find out more about how we could support your specific learning objectives, please get in touch'),
(15475, 607, '_full_width_components_1_text_under_bullets', 'field_5eaaa9e6b2cfb_field_5ed8c5ded99a4'),
