(15717, 608, '_full_width_components_10_buttons_1_button', 'field_5ed90856b39bb'),
(15718, 608, 'full_width_components_10_buttons', '2'),
(15719, 608, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(15720, 608, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(15721, 608, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(15722, 608, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(15723, 608, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(15724, 608, 'full_width_components_11_icons_0_icon', '504'),
(15725, 608, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(15726, 608, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(15727, 608, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(15728, 608, 'full_width_components_11_icons', '1'),
(15729, 608, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(15730, 608, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(15731, 608, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(15732, 608, 'full_width_components_12_text', 'Supporting Our Customers'),
(15733, 608, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(15734, 608, 'full_width_components_12_text_position', 'center'),
(15735, 608, '_full_width_components_12_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(15736, 608, 'full_width_components_12_background_image', '457'),
(15737, 608, '_full_width_components_12_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(15738, 608, 'full_width_components_13_two_column_content_0_column_style', 'image-left'),
(15739, 608, '_full_width_components_13_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(15740, 608, 'full_width_components_13_two_column_content_0_title', 'Support'),
(15741, 608, '_full_width_components_13_two_column_content_0_title', 'field_5ed8f3421c210'),
(15742, 608, 'full_width_components_13_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(15743, 608, '_full_width_components_13_two_column_content_0_text', 'field_5ed8f3421c225'),
(15744, 608, 'full_width_components_13_two_column_content_0_read_more_link', ''),
