(16259, 629, '_full_width_components_7_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(16260, 629, 'full_width_components_8_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(16261, 629, '_full_width_components_8_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(16262, 629, 'full_width_components_8_component_subtitle', ''),
(16263, 629, '_full_width_components_8_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(16264, 629, 'full_width_components_8_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(16265, 629, '_full_width_components_8_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(16266, 629, 'full_width_components_8_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
