(16396, 630, 'full_width_components_8_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(16397, 630, '_full_width_components_8_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(16398, 630, 'full_width_components_8_component_subtitle', ''),
(16399, 630, '_full_width_components_8_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(16400, 630, 'full_width_components_8_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(16401, 630, '_full_width_components_8_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(16402, 630, 'full_width_components_8_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(16403, 630, '_full_width_components_8_buttons_0_button', 'field_5eabf7d5bf1a9'),
(16404, 630, 'full_width_components_8_buttons', '1'),
(16405, 630, '_full_width_components_8_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(16406, 630, 'full_width_components_6_two_column_content_0_column_style', 'image-right'),
(16407, 630, '_full_width_components_6_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(16408, 630, 'full_width_components_6_two_column_content_0_title', ''),
(16409, 630, '_full_width_components_6_two_column_content_0_title', 'field_5ed8f3421c210'),
(16410, 630, 'full_width_components_6_two_column_content_0_text', 'Skills for Justice (SFJ) Awards is an awarding organisation approved by the Qualification Regulators to provide qualifications in England, Wales and Northern Ireland. We were awarded SFJ Centre Approval Status in November 2019 this allows our company to design and deliver accredited training globally under their Accredited Learning professionally (ALP) scheme.\r\n\r\nBy working with SFJ Awards, we can develop and implement accredited and certificated learning programmes that adhere to a recognised quality assurance process.\r\n\r\nThis results in a quality, collaborative, tailored training programme which allows our clients to have confidence in the learning product they create with us. It also ensures learners have the appropriate skills to do their jobs with proficiency.'),
(16411, 630, '_full_width_components_6_two_column_content_0_text', 'field_5ed8f3421c225'),
(16412, 630, 'full_width_components_6_two_column_content_0_read_more_link', ''),
