(16557, 631, '_full_width_components_6_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(16558, 631, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(16559, 631, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(16560, 631, 'full_width_components_4_two_column_content_0_title', ''),
(16561, 631, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(16562, 631, 'full_width_components_4_two_column_content_0_text', 'Before Cognitas Global was founded in 2018, we built our experience on delivering capacity building, training and technical assistance in 54 countries through our parent company <u>AML Consulting (Global).</u>\r\n\r\nSince 2011, we’ve worked with numerous clients, including the UK Foreign &amp; Commonwealth Office, Department for International Development (DfID), UK National Crime Agency and National Economic Crime Centre, the United Nations Office for Drugs &amp; Crime (UNODC), and the Organisation for Security and Cooperation in Europe (OSCE).\r\n\r\nMeanwhile, our sister company AML Consulting (Global) UK has held SFJ Approved Training Centre status since 2017. It leads on the design and global delivery of Skills for Justice Awards accredited training programmes.'),
(16563, 631, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
