(16986, 635, 'full_width_components_1_component_subtitle', ''),
(16987, 635, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(16988, 635, 'full_width_components_1_content', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and\r\nafterwards, the record of activity provides clear evidence that desired outcomes have been met'),
(16989, 635, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(16990, 635, 'full_width_components_1_buttons', ''),
(16991, 635, '_full_width_components_1_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(16992, 635, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(16993, 635, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(16994, 635, 'full_width_components_2_two_column_content_0_title', ''),
(16995, 635, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(16996, 635, 'full_width_components_2_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(16997, 635, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(16998, 635, 'full_width_components_2_two_column_content_0_read_more_link', ''),
