(17004, 635, 'full_width_components_2_two_column_content_1_title', ''),
(17005, 635, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(17006, 635, 'full_width_components_2_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
