(17717, 640, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(17718, 640, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(17719, 640, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(17720, 640, 'full_width_components_6_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(17721, 640, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(17722, 640, 'full_width_components_6_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:25:\"More about our philosophy\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(17723, 640, '_full_width_components_6_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(17724, 640, 'full_width_components_6_alternating_image_text_1_image', '335'),
(17725, 640, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(17726, 640, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(17727, 640, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(17728, 640, 'full_width_components_6_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(17729, 640, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(17730, 640, 'full_width_components_6_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
