(17797, 641, '_summary_image', 'field_5ea83004efb2d'),
(17798, 641, 'full_width_components_0_component_title', 'Does the competency of teams or individuals rely on the quality of the training or learning that you provide? '),
(17799, 641, '_full_width_components_0_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(17800, 641, 'full_width_components_0_component_subtitle', 'The View360 Global™ platform allows you to create bespoke learning solutions, in over 90 languages, with the full support of our expert team. '),
(17801, 641, '_full_width_components_0_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(17802, 641, 'full_width_components_0_icons', '5'),
