(17827, 641, '_full_width_components_1_image', 'field_5eaaa9e6b2cfb_field_5eaaa88084c4f'),
(17828, 641, 'full_width_components_1_title', 'About our learning platform'),
(17829, 641, '_full_width_components_1_title', 'field_5eaaa9e6b2cfb_field_5eaaa8a084c50'),
(17830, 641, 'full_width_components_1_subtitle', 'If you need to test and develop decision making skills, our versatile View360 Global™ platform allows you to create an immersive online learning environment tailored to meet your specific needs.  <br><br> Here are just some of the areas where our clients have discovered its advantages:'),
(17831, 641, '_full_width_components_1_subtitle', 'field_5eaaa9e6b2cfb_field_5eaaa8ad84c51'),
(17832, 641, 'full_width_components_1_left_side_bullet_points_0_bullet_point', 'Crisis management response'),
(17833, 641, '_full_width_components_1_left_side_bullet_points_0_bullet_point', 'field_5eaaa90784c56'),
(17834, 641, 'full_width_components_1_left_side_bullet_points_1_bullet_point', 'Compliance training'),
(17835, 641, '_full_width_components_1_left_side_bullet_points_1_bullet_point', 'field_5eaaa90784c56'),
(17836, 641, 'full_width_components_1_left_side_bullet_points_2_bullet_point', 'Business continuity planning'),
