(18201, 642, '_full_width_components_8_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(18202, 642, 'full_width_components_8_testimonials_0_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements.'),
(18203, 642, '_full_width_components_8_testimonials_0_text', 'field_5cac5d7b5b816'),
(18204, 642, 'full_width_components_8_testimonials_0_author', 'Happy View360 Global™ user'),
(18205, 642, '_full_width_components_8_testimonials_0_author', 'field_5eac2ec641dad'),
(18206, 642, 'full_width_components_8_testimonials_1_text', 'View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation. All of our communication was Cognitas Global Ltd was fantastic - their team took time to understand our organisation and made suggestions on our requirements. View360 Global™ was the ideal platform to provide Critical incident training that was tailored to my organisation.\r\n '),
(18207, 642, '_full_width_components_8_testimonials_1_text', 'field_5cac5d7b5b816'),
