(18367, 643, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(18368, 643, 'full_width_components_4_component_subtitle', '<strong>Our licencing plans and consultancy options</strong>'),
(18369, 643, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(18370, 643, 'full_width_components_4_content', 'The creation of your View360 Global™ learning solution is a collaborative process, with as much training, technical support and advice as you need from our experienced team.\r\n\r\nBy focusing on your specific operational requirements, budgets and timescales, we can help you choose the most cost-effective solution – be that a licencing plan or one of our consultancy services.'),
(18371, 643, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
