(18387, 643, '_full_width_components_5_call_to_actions', 'field_5eabdc9f59951_field_5eabdeb53131f'),
(18388, 643, 'full_width_components_6_alternating_image_text_0_title', 'Our Team'),
(18389, 643, '_full_width_components_6_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(18390, 643, 'full_width_components_6_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(18391, 643, '_full_width_components_6_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(18392, 643, 'full_width_components_6_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:19:\"More about the team\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(18393, 643, '_full_width_components_6_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(18394, 643, 'full_width_components_6_alternating_image_text_0_image', '334'),
(18395, 643, '_full_width_components_6_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(18396, 643, 'full_width_components_6_alternating_image_text_1_title', 'Our Philosophy'),
(18397, 643, '_full_width_components_6_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(18398, 643, 'full_width_components_6_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(18399, 643, '_full_width_components_6_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(18400, 643, 'full_width_components_6_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:25:\"More about our philosophy\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(18401, 643, '_full_width_components_6_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(18402, 643, 'full_width_components_6_alternating_image_text_1_image', '335'),
(18403, 643, '_full_width_components_6_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(18404, 643, 'full_width_components_6_alternating_image_text_2_title', 'Our Training Credentials'),
(18405, 643, '_full_width_components_6_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(18406, 643, 'full_width_components_6_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(18407, 643, '_full_width_components_6_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(18408, 643, 'full_width_components_6_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(18409, 643, '_full_width_components_6_alternating_image_text_2_read_more_link', 'field_5eac06535f1f3'),
