(18479, 645, '_full_width_components', 'field_5e3bd2cd0cde3'),
(18480, 645, 'full_width_components_0_two_column_content_0_column_style', 'image-left'),
(18481, 645, '_full_width_components_0_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(18482, 645, 'full_width_components_0_two_column_content_0_title', 'SMARTDESC Ltd'),
(18483, 645, '_full_width_components_0_two_column_content_0_title', 'field_5ed8f3421c210'),
(18484, 645, 'full_width_components_0_two_column_content_0_text', '<h1>The Challenge</h1>\r\nSmartdesc provide IT Strategy, Data Protection and Support services to the Not for Profit sector.\r\n\r\nSmartdesc had identified that a number of SME Charities were vulnerable to cyberattack and wished to co-host a pro bono educational training workshop where an immersive exercise would be delivered alongside a presentation from their IT experts in order to broaden the participants knowledge and awareness of IT Security best practices.'),
(18485, 645, '_full_width_components_0_two_column_content_0_text', 'field_5ed8f3421c225'),
(18486, 645, 'full_width_components_0_two_column_content_0_read_more_link', 'a:3:{s:5:\"title\";s:21:\"SMARTDESC Ltd Website\";s:3:\"url\";s:28:\"https://www.smartdesc.co.uk/\";s:6:\"target\";s:6:\"_blank\";}'),
(18487, 645, '_full_width_components_0_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
