(18495, 645, '_full_width_components_1_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(18496, 645, 'full_width_components_1_testimonials_0_text', '<br><br>\r\n“The Cognitas platform enabled us to simulate what a real ransomware attack might look and feel like; we could then challenge the delegates to make decisions that directly affected the outcome. This made the session feel very real, so the delegates were immersed in the training and got the maximum benefit from it. The feedback was outstanding”\r\n<br><br>'),
(18497, 645, '_full_width_components_1_testimonials_0_text', 'field_5cac5d7b5b816'),
(18498, 645, 'full_width_components_1_testimonials_0_author', 'James Field, Customer Strategy Director'),
(18499, 645, '_full_width_components_1_testimonials_0_author', 'field_5eac2ec641dad'),
(18500, 645, 'full_width_components_1_testimonials', '1'),
