(18503, 645, '_full_width_components_1_button', 'field_5eac2de411183_field_5eac2edad830e'),
(18504, 645, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(18505, 645, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(18506, 645, 'full_width_components_2_two_column_content_0_title', 'How We Assisted'),
(18507, 645, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(18508, 645, 'full_width_components_2_two_column_content_0_text', 'We worked closely with Andrew Coyle, Head of Information Security, and James Field, Strategy Director at Smartdesc, to build a ransomware attack scenario that was designed to educate the participants around the threat, response and building preventative measures, policy and resilience.\r\n\r\nSome 21 representatives from SME charities attended the half day workshop where a 2-hour exercise was delivered followed by a presentation'),
(18509, 645, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(18510, 645, 'full_width_components_2_two_column_content_0_read_more_link', ''),
(18511, 645, '_full_width_components_2_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(18512, 645, 'full_width_components_2_two_column_content_0_image', '465'),
(18513, 645, '_full_width_components_2_two_column_content_0_image', 'field_5ed8f3421c23f'),
(18514, 645, 'full_width_components_2_two_column_content_1_column_style', 'image-left'),
(18515, 645, '_full_width_components_2_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(18516, 645, 'full_width_components_2_two_column_content_1_title', 'What was Achieved'),
(18517, 645, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(18518, 645, 'full_width_components_2_two_column_content_1_text', 'Delivering the exercise on the platform without any pre warning of what to expect highlighted a significant number of vulnerabilities in the sector where many of the SMEs did not have the resources or knowledge of larger companies to mitigate cyberthreats. The participants were universal in their praise for the benefits of the workshop and the technical advice offered by Smartdesc, indicating that they were intending to implement what assistance had been offered.'),
(18519, 645, '_full_width_components_2_two_column_content_1_text', 'field_5ed8f3421c225'),
(18520, 645, 'full_width_components_2_two_column_content_1_read_more_link', ''),
