(18547, 646, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(18548, 646, 'full_width_components_2_two_column_content_0_text', 'Collaborating closely with EXPOL and their established clients, we co designed and delivered a series of independent and well attended blended learning training events, where the immersive scenarios and media content were specifically designed to meet the operational needs of the diverse beneficiary organisations'),
(18549, 646, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
