(18746, 650, '_full_width_components_8_gallery_items', 'field_5ed763b6b1690_field_5d8dbaaa76571'),
(18747, 650, 'full_width_components_9_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(18748, 650, '_full_width_components_9_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(18749, 650, 'full_width_components_10_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(18750, 650, '_full_width_components_10_buttons_0_button', 'field_5ed90856b39bb'),
(18751, 650, 'full_width_components_10_buttons_1_button', 'a:3:{s:5:\"title\";s:20:\"Book a Demonstration\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(18752, 650, '_full_width_components_10_buttons_1_button', 'field_5ed90856b39bb'),
(18753, 650, 'full_width_components_10_buttons', '2'),
(18754, 650, '_full_width_components_10_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(18755, 650, 'full_width_components_11_component_title', 'Immersive media - bringing creativity to life'),
(18756, 650, '_full_width_components_11_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(18757, 650, 'full_width_components_11_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(18758, 650, '_full_width_components_11_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(18759, 650, 'full_width_components_11_icons_0_icon', '504'),
(18760, 650, '_full_width_components_11_icons_0_icon', 'field_5ea984ddcbc5d'),
(18761, 650, 'full_width_components_11_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(18762, 650, '_full_width_components_11_icons_0_text', 'field_5ea984e6cbc5e'),
(18763, 650, 'full_width_components_11_icons', '1'),
(18764, 650, '_full_width_components_11_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(18765, 650, 'full_width_components_11_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(18766, 650, '_full_width_components_11_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
(18767, 650, 'full_width_components_12_text', 'Supporting Our Customers'),
(18768, 650, '_full_width_components_12_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(18769, 650, 'full_width_components_12_text_position', 'center'),
(18770, 650, '_full_width_components_12_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(18771, 650, 'full_width_components_12_background_image', '457'),
(18772, 650, '_full_width_components_12_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(18773, 650, 'full_width_components_13_two_column_content_0_column_style', 'image-right'),
(18774, 650, '_full_width_components_13_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(18775, 650, 'full_width_components_13_two_column_content_0_title', ''),
(18776, 650, '_full_width_components_13_two_column_content_0_title', 'field_5ed8f3421c210'),
(18777, 650, 'full_width_components_13_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(18778, 650, '_full_width_components_13_two_column_content_0_text', 'field_5ed8f3421c225'),
(18779, 650, 'full_width_components_13_two_column_content_0_read_more_link', ''),
(18780, 650, '_full_width_components_13_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
