(18793, 651, 'full_width_components', 'a:6:{i:0;s:12:\"text_content\";i:1;s:21:\"title-content-buttons\";i:2;s:18:\"two_column_content\";i:3;s:21:\"title-content-buttons\";i:4;s:15:\"text_over_image\";i:5;s:21:\"title-content-buttons\";}'),
(18794, 651, '_full_width_components', 'field_5e3bd2cd0cde3'),
(18795, 651, 'show_left_sidebar', '0'),
(18796, 651, '_show_left_sidebar', 'field_5e38357452128'),
(18797, 651, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(18798, 651, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(18799, 651, 'full_width_components_0_content', '<p style=\"text-align: center;\"><strong>Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</strong></p>'),
(18800, 651, '_full_width_components_0_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(18801, 651, 'full_width_components_1_component_title', 'Multilingual Data Capture'),
(18802, 651, '_full_width_components_1_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(18803, 651, 'full_width_components_1_component_subtitle', ''),
(18804, 651, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(18805, 651, 'full_width_components_1_content', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and\r\nafterwards, the record of activity provides clear evidence that desired outcomes have been met'),
(18806, 651, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(18807, 651, 'full_width_components_1_buttons', ''),
(18808, 651, '_full_width_components_1_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(18809, 651, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(18810, 651, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(18811, 651, 'full_width_components_2_two_column_content_0_title', ''),
(18812, 651, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(18813, 651, 'full_width_components_2_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(18814, 651, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(18815, 651, 'full_width_components_2_two_column_content_0_read_more_link', ''),
