(18818, 651, '_full_width_components_2_two_column_content_0_image', 'field_5ed8f3421c23f'),
(18819, 651, 'full_width_components_2_two_column_content_1_column_style', 'image-right'),
(18820, 651, '_full_width_components_2_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(18821, 651, 'full_width_components_2_two_column_content_1_title', ''),
(18822, 651, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(18823, 651, 'full_width_components_2_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
