(18993, 653, 'full_width_components_1_timeline_items_0_timeline_title', 'ANALYSIS'),
(18994, 653, '_full_width_components_1_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(18995, 653, 'full_width_components_1_timeline_items_0_timeline_content', 'The process begins with gap analysis to help us identify your specific requirements and the most cost-effective solution.'),
(18996, 653, '_full_width_components_1_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(18997, 653, 'full_width_components_1_timeline_items_1_timeline_title', 'DESIGN'),
(18998, 653, '_full_width_components_1_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(18999, 653, 'full_width_components_1_timeline_items_1_timeline_content', 'This is a collaborative process, drawing on the key principles of successful learning and development. <br><br> Using L&D principles, our consultants work with you to structure the learning to meet your operational needs <br><br> Our Graphic  Design Team can produce bespoke digital content and immersive media (IM) to ensure that by blending real world with authentic digital content, learners experience true reality '),
(19000, 653, '_full_width_components_1_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(19001, 653, 'full_width_components_1_timeline_items_2_timeline_title', 'TRAINIING'),
(19002, 653, '_full_width_components_1_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(19003, 653, 'full_width_components_1_timeline_items_2_timeline_content', ' Everything your delivery team and facilitators need to know to use the platform with confidence.'),
(19004, 653, '_full_width_components_1_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(19005, 653, 'full_width_components_1_timeline_items_3_timeline_title', 'DELIVERY'),
