(19261, 656, 'full_width_components_1_component_subtitle', ''),
(19262, 656, '_full_width_components_1_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(19263, 656, 'full_width_components_1_content', 'Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and\r\nafterwards, the record of activity provides clear evidence that desired outcomes have been met'),
(19264, 656, '_full_width_components_1_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(19265, 656, 'full_width_components_1_buttons', ''),
(19266, 656, '_full_width_components_1_buttons', 'field_5eabf9d6ed25f_field_5eabf7d5b9dd4'),
(19267, 656, 'full_width_components_2_two_column_content_0_column_style', 'image-left'),
(19268, 656, '_full_width_components_2_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(19269, 656, 'full_width_components_2_two_column_content_0_title', ''),
(19270, 656, '_full_width_components_2_two_column_content_0_title', 'field_5ed8f3421c210'),
(19271, 656, 'full_width_components_2_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(19272, 656, '_full_width_components_2_two_column_content_0_text', 'field_5ed8f3421c225'),
(19273, 656, 'full_width_components_2_two_column_content_0_read_more_link', ''),
