(19278, 656, '_full_width_components_2_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(19279, 656, 'full_width_components_2_two_column_content_1_title', ''),
(19280, 656, '_full_width_components_2_two_column_content_1_title', 'field_5ed8f3421c210'),
(19281, 656, 'full_width_components_2_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
(19282, 656, '_full_width_components_2_two_column_content_1_text', 'field_5ed8f3421c225'),
