(19289, 656, 'full_width_components_3_component_title', 'Measuring the impact of your learning'),
(19290, 656, '_full_width_components_3_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(19291, 656, 'full_width_components_3_component_subtitle', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
(19292, 656, '_full_width_components_3_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(19293, 656, 'full_width_components_3_content', '<img class=\"alignnone size-large wp-image-508\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-11.52.50-e1590749697636-1024x422.png\" alt=\"\" width=\"1024\" height=\"422\" />'),
(19294, 656, '_full_width_components_3_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(19295, 656, 'full_width_components_3_buttons', ''),
