(19322, 657, '_full_width_components_1_component_title', 'field_5eac2de411183_field_5cac57a344530'),
(19323, 657, 'full_width_components_1_testimonials_0_text', '<br><br>\r\n “The use of View360 Global engendered genuine interest with our Clients, who were able to experience something quite unique in the classroom.  This software had never been seen before by anyone and proved an instant hit with the audience, who were totally engaged and eager to participate in the workshop.  At its conclusion, they left having enjoyed a thoroughly new method of learning.   Its flexible, adaptable and has the potential to revolutionise the training environment.  We highly recommend it.  We will definitely be working with this in the future”   \r\n<br><br>'),
(19324, 657, '_full_width_components_1_testimonials_0_text', 'field_5cac5d7b5b816'),
(19325, 657, 'full_width_components_1_testimonials_0_author', 'Rob Kinrade CEO'),
