(20909, 675, 'full_width_components_5_buttons_0_button', 'a:3:{s:5:\"title\";s:11:\"Book a demo\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(20910, 675, '_full_width_components_5_buttons_0_button', 'field_5ed90856b39bb'),
(20911, 675, 'full_width_components_5_buttons', '1'),
(20912, 675, '_full_width_components_5_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(20913, 675, 'full_width_components_6_text', 'Supporting Our Customers'),
(20914, 675, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(20915, 675, 'full_width_components_6_text_position', 'center'),
(20916, 675, '_full_width_components_6_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(20917, 675, 'full_width_components_6_background_image', '457'),
(20918, 675, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(20919, 675, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(20920, 675, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(20921, 675, 'full_width_components_4_two_column_content_0_title', 'Facilitation'),
(20922, 675, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(20923, 675, 'full_width_components_4_two_column_content_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(20924, 675, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(20925, 675, 'full_width_components_4_two_column_content_0_read_more_link', ''),
(20926, 675, '_full_width_components_4_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(20927, 675, 'full_width_components_4_two_column_content_0_image', '649'),
(20928, 675, '_full_width_components_4_two_column_content_0_image', 'field_5ed8f3421c23f'),
(20929, 675, 'full_width_components_4_two_column_content_1_column_style', 'image-right'),
(20930, 675, '_full_width_components_4_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(20931, 675, 'full_width_components_4_two_column_content_1_title', 'The platform'),
(20932, 675, '_full_width_components_4_two_column_content_1_title', 'field_5ed8f3421c210'),
(20933, 675, 'full_width_components_4_two_column_content_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(20934, 675, '_full_width_components_4_two_column_content_1_text', 'field_5ed8f3421c225'),
(20935, 675, 'full_width_components_4_two_column_content_1_read_more_link', ''),
(20936, 675, '_full_width_components_4_two_column_content_1_read_more_link', 'field_5ed8f3421c235'),
(20937, 675, 'full_width_components_4_two_column_content_1_image', '496'),
(20938, 675, '_full_width_components_4_two_column_content_1_image', 'field_5ed8f3421c23f'),
(20939, 675, 'full_width_components_4_two_column_content_2_column_style', 'image-left'),
(20940, 675, '_full_width_components_4_two_column_content_2_column_style', 'field_5ed8f395410e1'),
(20941, 675, 'full_width_components_4_two_column_content_2_title', 'Virtual Conferencing'),
(20942, 675, '_full_width_components_4_two_column_content_2_title', 'field_5ed8f3421c210'),
(20943, 675, 'full_width_components_4_two_column_content_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(20944, 675, '_full_width_components_4_two_column_content_2_text', 'field_5ed8f3421c225'),
