(21389, 680, 'full_width_components_3_background_image', '457'),
(21390, 680, '_full_width_components_3_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(21391, 680, 'full_width_components_4_component_title', 'Assessing return on expectations (ROE)'),
(21392, 680, '_full_width_components_4_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(21393, 680, 'full_width_components_4_component_subtitle', 'A successful training initiative delivers a return on expectations to its key business stakeholders.'),
(21394, 680, '_full_width_components_4_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(21395, 680, 'full_width_components_4_content', 'It’s a practitioner approach to creating and demonstrating the organisational value of training – and shows clearly the degree to which expectations have been satisfied.\r\n\r\n<b>We use the established New World Kirkpatrick model to measure your ROE.</b>\r\n\r\nThis is one of a number of proven methodologies that we employ for the measurement of data as part of our <a href=\"https://cognitas.msonet.co.uk/consultancy-services/\"><u>consultancy services</u>.</a>\r\n\r\nAs certified Kirkpatrick model practitioners we can provide:\r\n<div style=\"display: flex; justify-content: center;\">\r\n<ul style=\"align-items: flex-start;\">\r\n 	<li>A full analysis of the training you’ve delivered</li>\r\n 	<li>Evidence of achieving outcomes and objectives</li>\r\n 	<li>Recommendations for continued professional development.</li>\r\n</ul>\r\n</div>\r\n<img class=\"alignnone wp-image-516 size-large\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/05/Screenshot-2020-05-29-at-12.02.35-e1590750284396-1024x532.png\" alt=\"\" width=\"1024\" height=\"532\" />'),
(21396, 680, '_full_width_components_4_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
