(22199, 687, 'full_width_components_4_text', 'Training designed by qualified practitioners'),
(22200, 687, '_full_width_components_4_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(22201, 687, 'full_width_components_4_text_position', 'center'),
