(22203, 687, 'full_width_components_4_background_image', '473'),
(22204, 687, '_full_width_components_4_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(22205, 687, 'full_width_components_5_two_column_content_0_column_style', 'image-right'),
(22206, 687, '_full_width_components_5_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(22207, 687, 'full_width_components_5_two_column_content_0_title', ''),
(22208, 687, '_full_width_components_5_two_column_content_0_title', 'field_5ed8f3421c210'),
(22209, 687, 'full_width_components_5_two_column_content_0_text', 'Skills for Justice (SFJ) Awards is an awarding organisation approved by the Qualification Regulators to provide qualifications in England, Wales and Northern Ireland. We were awarded SFJ Centre Approval Status in November 2019 this allows our company to design and deliver accredited training globally under their Accredited Learning professionally (ALP) scheme.\r\n\r\nBy working with SFJ Awards, we can develop and implement accredited and certificated learning programmes that adhere to a recognised quality assurance process.\r\n\r\nThis results in a quality, collaborative, tailored training programme which allows our clients to have confidence in the learning product they create with us. It also ensures learners have the appropriate skills to do their jobs with proficiency.'),
(22210, 687, '_full_width_components_5_two_column_content_0_text', 'field_5ed8f3421c225'),
(22211, 687, 'full_width_components_5_two_column_content_0_read_more_link', ''),
