(22217, 687, 'full_width_components_6_text', 'Working with the community'),
(22218, 687, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(22219, 687, 'full_width_components_6_text_position', 'center'),
