(22271, 688, 'full_width_components', 'a:9:{i:0;s:13:\"meet_the_team\";i:1;s:13:\"meet_the_team\";i:2;s:15:\"text_over_image\";i:3;s:18:\"two_column_content\";i:4;s:15:\"text_over_image\";i:5;s:18:\"two_column_content\";i:6;s:15:\"text_over_image\";i:7;s:21:\"title-content-buttons\";i:8;s:22:\"alternating_image_text\";}'),
(22272, 688, '_full_width_components', 'field_5e3bd2cd0cde3'),
(22273, 688, 'page_title_override', ''),
(22274, 688, '_page_title_override', 'field_5ea82fadefb2b'),
(22275, 688, 'page_summary', 'Delivering technical assistance worldwide & Working with the community'),
(22276, 688, '_page_summary', 'field_5ea82ff6efb2c'),
(22277, 688, 'summary_image', ''),
(22278, 688, '_summary_image', 'field_5ea83004efb2d'),
(22279, 688, 'components_0_content', '<p style=\"text-align: center;\">We’re a unique cadre of experienced practitioners with extensive experience of working in international jurisdictions, and across both the public and private sectors.</p>\r\n<p style=\"text-align: center;\">We bring a moral and ethical approach to the field of learning, with a deep appreciation of the complex challenges facing the different organisations we work with. Remaining flexible and pragmatic in our advice and solutions, we’re always prepared to adapt to the diverse environments in which we operate.</p>\r\n<p style=\"text-align: center;\">Our solutions are practical and realistic, based on Learning and Development principles that make it easier for you to achieve your objectives. It’s a proven approach that means we consistently deliver meaningful and sustainable transformational change – combined with real value for money.</p>\r\n&nbsp;'),
(22280, 688, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
