(22379, 688, 'full_width_components_7_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(22380, 688, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(22381, 688, 'full_width_components_7_component_subtitle', ''),
(22382, 688, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(22383, 688, 'full_width_components_7_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(22384, 688, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
