(22573, 689, 'full_width_components_3_component_title', 'What makes us different'),
(22574, 689, '_full_width_components_3_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(22575, 689, 'full_width_components_3_alternating_image_text_0_title', 'Our Team'),
(22576, 689, '_full_width_components_3_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(22577, 689, 'full_width_components_3_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(22578, 689, '_full_width_components_3_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(22579, 689, 'full_width_components_3_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(22580, 689, '_full_width_components_3_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(22581, 689, 'full_width_components_3_alternating_image_text_0_image', '334'),
(22582, 689, '_full_width_components_3_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(22583, 689, 'full_width_components_3_alternating_image_text_1_title', 'Our Philosophy'),
(22584, 689, '_full_width_components_3_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(22585, 689, 'full_width_components_3_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(22586, 689, '_full_width_components_3_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(22587, 689, 'full_width_components_3_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(22588, 689, '_full_width_components_3_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(22589, 689, 'full_width_components_3_alternating_image_text_1_image', '335'),
(22590, 689, '_full_width_components_3_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(22591, 689, 'full_width_components_3_alternating_image_text_2_title', 'Our Training Credentials'),
(22592, 689, '_full_width_components_3_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(22593, 689, 'full_width_components_3_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(22594, 689, '_full_width_components_3_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(22595, 689, 'full_width_components_3_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(22596, 689, '_full_width_components_3_alternating_image_text_2_read_more_link', 'field_5eac06535f1f3'),
(22597, 689, 'full_width_components_3_alternating_image_text_2_image', '334'),
(22598, 689, '_full_width_components_3_alternating_image_text_2_image', 'field_5e70f0ef0dfd6'),
(22599, 689, 'full_width_components_3_alternating_image_text', '3'),
(22600, 689, '_full_width_components_3_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(22601, 689, 'full_width_components_4_two_column_content_0_column_style', 'image-left'),
(22602, 689, '_full_width_components_4_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(22603, 689, 'full_width_components_4_two_column_content_0_title', ''),
(22604, 689, '_full_width_components_4_two_column_content_0_title', 'field_5ed8f3421c210'),
(22605, 689, 'full_width_components_4_two_column_content_0_text', 'Before Cognitas Global was founded in 2018, we built our experience on delivering capacity building, training and technical assistance in 54 countries through our parent company <u>AML Consulting (Global).</u>\r\n\r\nSince 2011, we’ve worked with numerous clients, including the UK Foreign &amp; Commonwealth Office, Department for International Development (DfID), UK National Crime Agency and National Economic Crime Centre, the United Nations Office for Drugs &amp; Crime (UNODC), and the Organisation for Security and Cooperation in Europe (OSCE).\r\n\r\nMeanwhile, our sister company AML Consulting (Global) UK has held SFJ Approved Training Centre status since 2017. It leads on the design and global delivery of Skills for Justice Awards accredited training programmes.'),
(22606, 689, '_full_width_components_4_two_column_content_0_text', 'field_5ed8f3421c225'),
(22607, 689, 'full_width_components_4_two_column_content_0_read_more_link', ''),
(22608, 689, '_full_width_components_4_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
