(22805, 690, 'full_width_components_2_alternating_image_text_0_image', '334'),
(22806, 690, '_full_width_components_2_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(22807, 690, 'full_width_components_2_alternating_image_text_1_title', 'Our Philosophy'),
(22808, 690, '_full_width_components_2_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(22809, 690, 'full_width_components_2_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(22810, 690, '_full_width_components_2_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(22811, 690, 'full_width_components_2_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(22812, 690, '_full_width_components_2_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(22813, 690, 'full_width_components_2_alternating_image_text_1_image', '335'),
(22814, 690, '_full_width_components_2_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(22815, 690, 'full_width_components_2_alternating_image_text_2_title', 'Our Training Credentials'),
(22816, 690, '_full_width_components_2_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(22817, 690, 'full_width_components_2_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(22818, 690, '_full_width_components_2_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(22819, 690, 'full_width_components_2_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(22820, 690, '_full_width_components_2_alternating_image_text_2_read_more_link', 'field_5eac06535f1f3'),
