(22970, 691, '_full_width_components_1_video', 'field_5eaaa9e6b2cfb_field_5eaaa98d84c5b'),
(22971, 691, 'full_width_components_1_button', 'a:3:{s:5:\"title\";s:20:\"Book a Demonstration\";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(22972, 691, '_full_width_components_1_button', 'field_5eaaa9e6b2cfb_field_5eaaa9ac84c5c'),
(22973, 691, 'full_width_components_1_tabbed_content_1_tab_title', 'Connect'),
(22974, 691, '_full_width_components_1_tabbed_content_1_tab_title', 'field_5eaaa92b84c58'),
(22975, 691, 'full_width_components_1_tabbed_content_1_tab_content', 'With the potential to engage learners around the world, the platform is a powerful tool for collaborative working. It brings people and teams with different skill sets together to experience and gain insights from the unique perspectives of others. <br><br>Facilitators have real-time visibility of participants’ progress during the training enabling agile, responsive facilitation with a consistent focus on the knowledge gaps that need to be addressed. This significantly reduces training time and ensures value for money. '),
(22976, 691, '_full_width_components_1_tabbed_content_1_tab_content', 'field_5eaaa93b84c59'),
(22977, 691, 'full_width_components_1_tabbed_content_1_read_more_link', ''),
(22978, 691, '_full_width_components_1_tabbed_content_1_read_more_link', 'field_5eaaa95784c5a'),
(22979, 691, 'full_width_components_1_tabbed_content_2_tab_title', 'Measure'),
(22980, 691, '_full_width_components_1_tabbed_content_2_tab_title', 'field_5eaaa92b84c58'),
(22981, 691, 'full_width_components_1_tabbed_content_2_tab_content', 'View360 Global™ is an approved group learning tool that also allows you to assess  and analyse the performance of individuals.  <br><br>  You can monitor participants’ responses in real-time and, after the event, you will receive a comprehensive record of activity. This provides clear evidence that outcomes have been met – an essential requirement if the training is part of an accredited learning process. <br><br>'),
(22982, 691, '_full_width_components_1_tabbed_content_2_tab_content', 'field_5eaaa93b84c59'),
(22983, 691, 'full_width_components_1_tabbed_content_2_read_more_link', 'a:3:{s:5:\"title\";s:32:\" More about measurable results >\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
