(23250, 692, '_full_width_components_7_testimonials_0_title', 'field_5cac5d735b815'),
(23251, 692, 'full_width_components_1_tabbed_content_3_tab_title', 'Immerse'),
(23252, 692, '_full_width_components_1_tabbed_content_3_tab_title', 'field_5eaaa92b84c58'),
(23253, 692, 'full_width_components_1_tabbed_content_3_tab_content', 'Our platform allows you to customise training programmes using mixed media to help recreate real-life situations. Meaningful and relevant for those taking part, it engages in ways that conventional and non-blended learning can’t. <br><br>   Participants work in small groups or as individuals and can communicate directly with the facilitator in their native language. This safe learning environment allows knowledge to be assimilated in less time, improves retention and has been proved to increase productivity. <br><br>'),
(23254, 692, '_full_width_components_1_tabbed_content_3_tab_content', 'field_5eaaa93b84c59'),
(23255, 692, 'full_width_components_1_tabbed_content_3_read_more_link', 'a:3:{s:5:\"title\";s:35:\" More about immersive learning >  \";s:3:\"url\";s:41:\"https://cognitas.msonet.co.uk/components/\";s:6:\"target\";s:0:\"\";}'),
(23256, 692, '_full_width_components_1_tabbed_content_3_read_more_link', 'field_5eaaa95784c5a'),
(23257, 692, 'full_width_components_1_text_under_bullets', 'We work with organisations from both the public and private sectors, including those following statutory or mandatory  training requirements.  <BR><BR> To find out more about how we could support your specific learning objectives, please get in touch'),
