(24436, 704, '_full_width_components_6_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(24437, 704, 'full_width_components_7_text', 'Working with the community'),
(24438, 704, '_full_width_components_7_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(24439, 704, 'full_width_components_7_text_position', 'center'),
(24440, 704, '_full_width_components_7_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(24441, 704, 'full_width_components_7_background_image', '490'),
(24442, 704, '_full_width_components_7_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(24443, 704, 'full_width_components_8_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(24444, 704, '_full_width_components_8_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(24445, 704, 'full_width_components_8_component_subtitle', ''),
(24446, 704, '_full_width_components_8_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(24447, 704, 'full_width_components_8_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(24448, 704, '_full_width_components_8_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
