(24454, 704, '_full_width_components_3_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(24455, 704, 'full_width_components_3_two_column_content_0_column_style', 'image-left'),
(24456, 704, '_full_width_components_3_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(24457, 704, 'full_width_components_3_two_column_content_0_title', ''),
(24458, 704, '_full_width_components_3_two_column_content_0_title', 'field_5ed8f3421c210'),
(24459, 704, 'full_width_components_3_two_column_content_0_text', 'Before Cognitas Global was founded in 2018, we built our experience on delivering capacity building, training and technical assistance in 54 countries through our parent company <u>AML Consulting (Global).</u>\r\n\r\nSince 2011, we’ve worked with numerous clients, including the UK Foreign &amp; Commonwealth Office, Department for International Development (DfID), UK National Crime Agency and National Economic Crime Centre, the United Nations Office for Drugs &amp; Crime (UNODC), and the Organisation for Security and Cooperation in Europe (OSCE).\r\n\r\nMeanwhile, our sister company AML Consulting (Global) UK has held SFJ Approved Training Centre status since 2017. It leads on the design and global delivery of Skills for Justice Awards accredited training programmes.'),
(24460, 704, '_full_width_components_3_two_column_content_0_text', 'field_5ed8f3421c225'),
(24461, 704, 'full_width_components_3_two_column_content_0_read_more_link', ''),
(24462, 704, '_full_width_components_3_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
