(24584, 706, '_full_width_components_1_right_side_bullet_points_2_bullet_point', 'field_5eaaa8fe84c55'),
(24585, 706, 'full_width_components_1_right_side_bullet_points', '3'),
(24586, 706, '_full_width_components_1_right_side_bullet_points', 'field_5eaaa9e6b2cfb_field_5eaaa8f384c54'),
(24587, 706, 'full_width_components_1_tabbed_content_0_tab_title', 'Simplify'),
(24588, 706, '_full_width_components_1_tabbed_content_0_tab_title', 'field_5eaaa92b84c58'),
(24589, 706, 'full_width_components_1_tabbed_content_0_tab_content', 'View360 Global™ training can be delivered in the workplace or remotely, with participants in multiple locations. No complex IT infrastructure is required – it works on any computer using Chrome or Firefox. And because the platform is multilingual, everyone can participate in their own language. <br><br>  It’s also easy to use, which means minimal training time is required to ensure facilitators and participants are up to speed. Where internet access is unavailable, we also offer a LAN version.'),
(24590, 706, '_full_width_components_1_tabbed_content_0_tab_content', 'field_5eaaa93b84c59'),
(24591, 706, 'full_width_components_1_tabbed_content_0_read_more_link', ''),
