(25027, 708, 'full_width_components_7_text', 'Working with the community'),
(25028, 708, '_full_width_components_7_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(25029, 708, 'full_width_components_7_text_position', 'center'),
