(25207, 709, 'full_width_components_2_team_members_0_name', 'James Robinson'),
(25208, 709, '_full_width_components_2_team_members_0_name', 'field_5e662f2fae095'),
(25209, 709, 'full_width_components_2_team_members_0_title', 'Technical Director'),
(25210, 709, '_full_width_components_2_team_members_0_title', 'field_5e6630f53495d'),
(25211, 709, 'full_width_components_2_team_members_0_background_image', '479'),
(25212, 709, '_full_width_components_2_team_members_0_background_image', 'field_5e662f3eae096'),
(25213, 709, 'full_width_components_2_team_members_0_content', 'James has spent 13 years as a software architect and developer in the telecommunications and mobile apps industry. He has been a lead engineer in many deployments of software from mainframes to mobile phones. He now specialises in web frameworks and serverless infrastructure, having moved from corporate industry, to design agency, to now working independently as a freelance IT consultant. James has been working on the development of View360 Global since 2017 and was appointed the Technical Director of Cognitas in 2019.'),
(25214, 709, '_full_width_components_2_team_members_0_content', 'field_5e662f4cae097'),
(25215, 709, 'full_width_components_2_team_members_1_name', 'Nicola Argent'),
