(25287, 709, 'full_width_components_7_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(25288, 709, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(25289, 709, 'full_width_components_7_component_subtitle', ''),
(25290, 709, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(25291, 709, 'full_width_components_7_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(25292, 709, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
