(26430, 744, '_full_width_components_2_team_members', 'field_5eda47d03c7cb_field_5e662f17ae094'),
(26431, 744, 'full_width_components_3_component_title', 'What makes us different'),
(26432, 744, '_full_width_components_3_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(26433, 744, 'full_width_components_3_alternating_image_text_0_title', 'Our Team'),
(26434, 744, '_full_width_components_3_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(26435, 744, 'full_width_components_3_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(26436, 744, '_full_width_components_3_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(26437, 744, 'full_width_components_3_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(26438, 744, '_full_width_components_3_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(26439, 744, 'full_width_components_3_alternating_image_text_0_image', '334'),
(26440, 744, '_full_width_components_3_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(26441, 744, 'full_width_components_3_alternating_image_text_1_title', 'Our Philosophy'),
(26442, 744, '_full_width_components_3_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(26443, 744, 'full_width_components_3_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(26444, 744, '_full_width_components_3_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(26445, 744, 'full_width_components_3_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(26446, 744, '_full_width_components_3_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(26447, 744, 'full_width_components_3_alternating_image_text_1_image', '335'),
(26448, 744, '_full_width_components_3_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(26449, 744, 'full_width_components_3_alternating_image_text_2_title', 'Our Training Credentials'),
(26450, 744, '_full_width_components_3_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(26451, 744, 'full_width_components_3_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(26452, 744, '_full_width_components_3_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(26453, 744, 'full_width_components_3_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(26454, 744, '_full_width_components_3_alternating_image_text_2_read_more_link', 'field_5eac06535f1f3'),
(26455, 744, 'full_width_components_3_alternating_image_text_2_image', '334'),
(26456, 744, '_full_width_components_3_alternating_image_text_2_image', 'field_5e70f0ef0dfd6'),
(26457, 744, 'full_width_components_3_alternating_image_text', '3'),
(26458, 744, '_full_width_components_3_alternating_image_text', 'field_5eac01fd2e75f_field_5e70f08f518b7'),
(26459, 744, 'full_width_components_4_text', 'Training designed by qualified practitioners'),
(26460, 744, '_full_width_components_4_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(26461, 744, 'full_width_components_4_text_position', 'center'),
(26462, 744, '_full_width_components_4_text_position', 'field_5eabd11823e61_field_5eda1cea2eec0'),
(26463, 744, 'full_width_components_4_background_image', '473'),
(26464, 744, '_full_width_components_4_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
