(26484, 744, '_full_width_components_6_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(26485, 744, 'full_width_components_7_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(26486, 744, '_full_width_components_7_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(26487, 744, 'full_width_components_7_component_subtitle', ''),
(26488, 744, '_full_width_components_7_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(26489, 744, 'full_width_components_7_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(26490, 744, '_full_width_components_7_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
