(26515, 746, 'full_width_components', 'a:6:{i:0;s:12:\"text_content\";i:1;s:18:\"two_column_content\";i:2;s:21:\"title-content-buttons\";i:3;s:15:\"text_over_image\";i:4;s:21:\"title-content-buttons\";i:5;s:12:\"infographics\";}'),
(26516, 746, '_full_width_components', 'field_5e3bd2cd0cde3'),
(26517, 746, 'show_left_sidebar', '0'),
(26518, 746, '_show_left_sidebar', 'field_5e38357452128'),
(26519, 746, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(26520, 746, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(26521, 746, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(26522, 746, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(26523, 746, 'full_width_components_1_two_column_content_0_title', ''),
(26524, 746, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(26525, 746, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(26526, 746, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(26527, 746, 'full_width_components_1_two_column_content_0_read_more_link', ''),
