(27403, 766, 'show_left_sidebar', '0'),
(27404, 766, '_show_left_sidebar', 'field_5e38357452128'),
(27405, 766, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(27406, 766, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(27407, 766, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(27408, 766, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(27409, 766, 'full_width_components_1_two_column_content_0_title', ''),
(27410, 766, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(27411, 766, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(27412, 766, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(27413, 766, 'full_width_components_1_two_column_content_0_read_more_link', ''),
(27414, 766, '_full_width_components_1_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(27415, 766, 'full_width_components_1_two_column_content_0_image', '310'),
(27416, 766, '_full_width_components_1_two_column_content_0_image', 'field_5ed8f3421c23f'),
(27417, 766, 'full_width_components_1_two_column_content_1_column_style', 'image-right'),
(27418, 766, '_full_width_components_1_two_column_content_1_column_style', 'field_5ed8f395410e1'),
(27419, 766, 'full_width_components_1_two_column_content_1_title', ''),
(27420, 766, '_full_width_components_1_two_column_content_1_title', 'field_5ed8f3421c210'),
(27421, 766, 'full_width_components_1_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
(27422, 766, '_full_width_components_1_two_column_content_1_text', 'field_5ed8f3421c225'),
