(27535, 767, 'show_left_sidebar', '0'),
(27536, 767, '_show_left_sidebar', 'field_5e38357452128'),
(27537, 767, 'components_0_content', '<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</p>\r\n\r\n<h1 style=\"text-align: center;\">Multilingual Data Capture</h1>\r\n\r\n<p style=\"padding-left: 180px; padding-right: 180px; text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met.</p>'),
(27538, 767, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(27539, 767, 'full_width_components_1_two_column_content_0_column_style', 'image-left'),
(27540, 767, '_full_width_components_1_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(27541, 767, 'full_width_components_1_two_column_content_0_title', ''),
(27542, 767, '_full_width_components_1_two_column_content_0_title', 'field_5ed8f3421c210'),
(27543, 767, 'full_width_components_1_two_column_content_0_text', 'Whether evidencing an individual’s progress or the success of a group activity, the data records can be used by external auditing agencies for quality assurance purposes if you need to provide proof of learning outcomes. This is vital if the training is part of an accredited learning process.'),
(27544, 767, '_full_width_components_1_two_column_content_0_text', 'field_5ed8f3421c225'),
(27545, 767, 'full_width_components_1_two_column_content_0_read_more_link', ''),
