(27649, 769, 'full_width_components_1_component_title', 'How we work with you'),
(27650, 769, '_full_width_components_1_component_title', 'field_5ed7645bb169a_field_5ebd01f5d7bfb'),
(27651, 769, 'full_width_components_1_component_summary', ''),
