(27777, 781, '_components', 'field_5946685e2c4cd'),
(27778, 781, 'full_width_components', 'a:4:{i:0;s:18:\"two_column_content\";i:1;s:17:\"numbered_timeline\";i:2;s:12:\"text_content\";i:3;s:12:\"button_group\";}'),
(27779, 781, '_full_width_components', 'field_5e3bd2cd0cde3'),
(27780, 781, 'show_left_sidebar', '0'),
(27781, 781, '_show_left_sidebar', 'field_5e38357452128'),
(27782, 781, 'full_width_components_0_two_column_content_0_column_style', 'image-right'),
(27783, 781, '_full_width_components_0_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(27784, 781, 'full_width_components_0_two_column_content_0_title', 'You lead – we listen, support and advise '),
(27785, 781, '_full_width_components_0_two_column_content_0_title', 'field_5ed8f3421c210'),
(27786, 781, 'full_width_components_0_two_column_content_0_text', 'We know our clients want meaningful, cost-effective learning solutions. Exactly what that looks like depends on your specific objectives, timeframes and budget. We’ll spend time getting a clear understanding of what those are.\r\n\r\nWith our established Learning and Development credentials, we have the expertise to help you turn your objectives into a clear strategy. You’ll be able to deliver a meaningful learning experience that engages your audience and supports their progress, both individually and, if applicable, as part of a team.\r\n\r\n<b>Are you paying an annual licence for our platform? </b>\r\n\r\nYou can still benefit from our consultants’ considerable knowledge and experience. <a href=\"https://cognitas.msonet.co.uk/contact/\"><u>Get in touch</u></a> to talk through your options.'),
(27787, 781, '_full_width_components_0_two_column_content_0_text', 'field_5ed8f3421c225'),
(27788, 781, 'full_width_components_0_two_column_content_0_read_more_link', ''),
(27789, 781, '_full_width_components_0_two_column_content_0_read_more_link', 'field_5ed8f3421c235'),
(27790, 781, 'full_width_components_0_two_column_content_0_image', '572'),
(27791, 781, '_full_width_components_0_two_column_content_0_image', 'field_5ed8f3421c23f'),
