(27793, 781, '_full_width_components_0_two_column_content', 'field_5ed8f49bb1b3b_field_5ed8f34218c2e'),
(27794, 781, 'full_width_components_1_component_title', 'How we work with you'),
(27795, 781, '_full_width_components_1_component_title', 'field_5ed7645bb169a_field_5ebd01f5d7bfb'),
(27796, 781, 'full_width_components_1_component_summary', ''),
(27797, 781, '_full_width_components_1_component_summary', 'field_5ed7645bb169a_field_5ebd071af49f2'),
(27798, 781, 'full_width_components_1_timeline_items_0_timeline_title', 'ANALYSIS'),
(27799, 781, '_full_width_components_1_timeline_items_0_timeline_title', 'field_5ebd0237d7bfd'),
(27800, 781, 'full_width_components_1_timeline_items_0_timeline_content', 'The process begins with gap analysis to help us identify your specific requirements and the most cost-effective solution.'),
(27801, 781, '_full_width_components_1_timeline_items_0_timeline_content', 'field_5ebd023fd7bfe'),
(27802, 781, 'full_width_components_1_timeline_items_1_timeline_title', 'DESIGN'),
(27803, 781, '_full_width_components_1_timeline_items_1_timeline_title', 'field_5ebd0237d7bfd'),
(27804, 781, 'full_width_components_1_timeline_items_1_timeline_content', 'This is a collaborative process, drawing on the key principles of successful learning and development. <br><br> Using L&D principles, our consultants work with you to structure the learning to meet your operational needs <br><br> Our Graphic  Design Team can produce bespoke digital content and immersive media (IM) to ensure that by blending real world with authentic digital content, learners experience true reality '),
(27805, 781, '_full_width_components_1_timeline_items_1_timeline_content', 'field_5ebd023fd7bfe'),
(27806, 781, 'full_width_components_1_timeline_items_2_timeline_title', 'TRAINIING'),
(27807, 781, '_full_width_components_1_timeline_items_2_timeline_title', 'field_5ebd0237d7bfd'),
(27808, 781, 'full_width_components_1_timeline_items_2_timeline_content', ' Everything your delivery team and facilitators need to know to use the platform with confidence.'),
(27809, 781, '_full_width_components_1_timeline_items_2_timeline_content', 'field_5ebd023fd7bfe'),
(27810, 781, 'full_width_components_1_timeline_items_3_timeline_title', 'DELIVERY'),
(27811, 781, '_full_width_components_1_timeline_items_3_timeline_title', 'field_5ebd0237d7bfd'),
(27812, 781, 'full_width_components_1_timeline_items_3_timeline_content', 'If we’re not delivering the training for you, our practitioner experts will support you through the process.'),
(27813, 781, '_full_width_components_1_timeline_items_3_timeline_content', 'field_5ebd023fd7bfe'),
