(28344, 790, 'full_width_components_1_two_column_content_1_title', ''),
(28345, 790, '_full_width_components_1_two_column_content_1_title', 'field_5ed8f3421c210'),
(28346, 790, 'full_width_components_1_two_column_content_1_text', 'View360 Global™ captures the learning activity in native language and translated formats. This creates a comprehensive record in MS Word format allowing for in-depth analysis of both performance and results.'),
(28347, 790, '_full_width_components_1_two_column_content_1_text', 'field_5ed8f3421c225'),
