(28356, 790, 'full_width_components_0_content', '<h1 style=\"text-align: center;\">Simply delivering the learning is not enough. The measurement and analysis of recorded data is critical for laying the foundations of sustainable organisational growth.</h1>\r\n&nbsp;\r\n<h2 style=\"text-align: center;\">Multilingual Data Capture</h2>\r\n<p style=\"text-align: center;\">Real-time monitoring enables the facilitator to review participants’ progress during the learning experience – and afterwards, the record of activity provides clear evidence that desired outcomes have been met</p>'),
(28357, 790, '_full_width_components_0_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(28358, 790, 'full_width_components_2_component_title', 'Measuring the impact of your learning'),
(28359, 790, '_full_width_components_2_component_title', 'field_5ef318287c995_field_5ef317911c4c5'),
(28360, 790, 'full_width_components_2_component_summary', 'In order to know whether your learning strategy is having a positive impact – and meeting your learning and development objectives – reviewing the process and analysing the results is essential'),
