(28436, 792, 'components_0_timeline_items_0_timeline_title', 'User FriendlyINSERT INTO `wpcu_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(28642, 793, 'full_width_components_4_alternating_image_text_0_text', 'Facilitation can either be delivered to participants within the same premises (who do not necessarily have to be located in the same room) or alternatively throughout various locations nationally. This may suit smaller organizations who wish to deliver single language collaborative training in house or across regional offices.'),
(28643, 793, '_full_width_components_4_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(28644, 793, 'full_width_components_4_alternating_image_text_0_read_more_link', ''),
(28645, 793, '_full_width_components_4_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(28646, 793, 'full_width_components_4_alternating_image_text_0_image', '649'),
(28647, 793, '_full_width_components_4_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(28648, 793, 'full_width_components_4_alternating_image_text_1_title', 'The platform'),
(28649, 793, '_full_width_components_4_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(28650, 793, 'full_width_components_4_alternating_image_text_1_text', 'The platform can deliver learning to people who are participating simultaneously in one or more countries and each in their own language. Responses and exchanges between the facilitator and are received in their native language which enables innovative multinational training that may have previously been a challenge to achieve.'),
(28651, 793, '_full_width_components_4_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(28652, 793, 'full_width_components_4_alternating_image_text_1_read_more_link', ''),
(28653, 793, '_full_width_components_4_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(28654, 793, 'full_width_components_4_alternating_image_text_1_image', '496'),
(28655, 793, '_full_width_components_4_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(28656, 793, 'full_width_components_4_alternating_image_text_2_title', 'Virtual Conferencing'),
(28657, 793, '_full_width_components_4_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(28658, 793, 'full_width_components_4_alternating_image_text_2_text', 'Using virtual conference platforms that provide breakout room functionality will allow people speaking a common language to collaborate as a group whilst the learning can be facilitated from another country. This may be particularly suitable for global organisations, testing policy, resilience or business continuity.'),
(28659, 793, '_full_width_components_4_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(28660, 793, 'full_width_components_4_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:27:\"Contact us to find out more\";s:3:\"url\";s:8:\"/contact\";s:6:\"target\";s:0:\"\";}'),
