(28762, 795, 'full_width_components', 'a:8:{i:0;s:21:\"title-content-buttons\";i:1;s:13:\"meet_the_team\";i:2;s:13:\"meet_the_team\";i:3;s:22:\"alternating_image_text\";i:4;s:15:\"text_over_image\";i:5;s:18:\"two_column_content\";i:6;s:15:\"text_over_image\";i:7;s:21:\"title-content-buttons\";}'),
(28763, 795, '_full_width_components', 'field_5e3bd2cd0cde3'),
(28764, 795, 'page_title_override', ''),
(28765, 795, '_page_title_override', 'field_5ea82fadefb2b'),
(28766, 795, 'page_summary', 'Delivering technical assistance worldwide & Working with the community'),
(28767, 795, '_page_summary', 'field_5ea82ff6efb2c'),
(28768, 795, 'summary_image', ''),
(28769, 795, '_summary_image', 'field_5ea83004efb2d'),
(28770, 795, 'components_0_content', '<p style=\"text-align: center;\">We’re a unique cadre of experienced practitioners with extensive experience of working in international jurisdictions, and across both the public and private sectors.</p>\r\n<p style=\"text-align: center;\">We bring a moral and ethical approach to the field of learning, with a deep appreciation of the complex challenges facing the different organisations we work with. Remaining flexible and pragmatic in our advice and solutions, we’re always prepared to adapt to the diverse environments in which we operate.</p>\r\n<p style=\"text-align: center;\">Our solutions are practical and realistic, based on Learning and Development principles that make it easier for you to achieve your objectives. It’s a proven approach that means we consistently deliver meaningful and sustainable transformational change – combined with real value for money.</p>\r\n&nbsp;'),
(28771, 795, '_components_0_content', 'field_5953824b18a1c_field_5953822b26d50'),
(28772, 795, 'full_width_components_1_component_title', 'Our Board'),
(28773, 795, '_full_width_components_1_component_title', 'field_5eda47d03c7cb_field_5eda4a06219d4'),
(28774, 795, 'full_width_components_1_team_members_0_name', 'Colin Burrow '),
(28775, 795, '_full_width_components_1_team_members_0_name', 'field_5e662f2fae095'),
(28776, 795, 'full_width_components_1_team_members_0_title', 'Director'),
(28777, 795, '_full_width_components_1_team_members_0_title', 'field_5e6630f53495d'),
