(28795, 795, '_full_width_components_1_team_members_2_background_image', 'field_5e662f3eae096'),
(28796, 795, 'full_width_components_1_team_members_2_content', 'John spent 30 years in commercial, retail and offshore banking before joining HM Revenue &amp; Customs Criminal Investigation where he worked as a Specialist Financial Investigator for 12 years.  His banking career included commercial/retail loans, bids/deals and fund administration plus CEO of three small banks in the UK where he was appointed by the institutional shareholders to “rescue” and sell the businesses under supervision by the Bank of England.  For the last eighteen years John has lectured on \"Criminal Finance”, as a Fellow of Teesside Business School, to all branches of Law Enforcement in the UK. And has travelled the world extensively delivering training and technical assistance as a Subject Matter Expert'),
(28797, 795, '_full_width_components_1_team_members_2_content', 'field_5e662f4cae097'),
(28798, 795, 'full_width_components_1_team_members', '3'),
(28799, 795, '_full_width_components_1_team_members', 'field_5eda47d03c7cb_field_5e662f17ae094'),
(28800, 795, 'full_width_components_0_component_title', 'Cognitas Global Ltd aims to prompt a paradigm shift in education, learning & development for the private and public sectors with the multilingual immersive training platform View360 Global™. '),
(28801, 795, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(28802, 795, 'full_width_components_0_component_subtitle', 'Our vision is to offer ground-breaking cost effective and sustainable blended learning solutions '),
