(28809, 795, '_full_width_components_2_component_title', 'field_5eda47d03c7cb_field_5eda4a06219d4'),
(28810, 795, 'full_width_components_2_team_members_0_name', 'James Robinson'),
(28811, 795, '_full_width_components_2_team_members_0_name', 'field_5e662f2fae095'),
(28812, 795, 'full_width_components_2_team_members_0_title', 'Technical Director'),
(28813, 795, '_full_width_components_2_team_members_0_title', 'field_5e6630f53495d'),
(28814, 795, 'full_width_components_2_team_members_0_background_image', '727'),
(28815, 795, '_full_width_components_2_team_members_0_background_image', 'field_5e662f3eae096'),
(28816, 795, 'full_width_components_2_team_members_0_content', 'James has spent 13 years as a software architect and developer in the telecommunications and mobile apps industry. He has been a lead engineer in many deployments of software from mainframes to mobile phones. He now specialises in web frameworks and serverless infrastructure, having moved from corporate industry, to design agency, to now working independently as a freelance IT consultant. James has been working on the development of View360 Global since 2017 and was appointed the Technical Director of Cognitas in 2019.'),
(28817, 795, '_full_width_components_2_team_members_0_content', 'field_5e662f4cae097'),
