(28837, 795, '_full_width_components_3_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(28838, 795, 'full_width_components_3_alternating_image_text_0_title', 'Our Team'),
(28839, 795, '_full_width_components_3_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(28840, 795, 'full_width_components_3_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(28841, 795, '_full_width_components_3_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(28842, 795, 'full_width_components_3_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(28843, 795, '_full_width_components_3_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(28844, 795, 'full_width_components_3_alternating_image_text_0_image', '334'),
(28845, 795, '_full_width_components_3_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(28846, 795, 'full_width_components_3_alternating_image_text_1_title', 'Our Philosophy'),
(28847, 795, '_full_width_components_3_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(28848, 795, 'full_width_components_3_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(28849, 795, '_full_width_components_3_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(28850, 795, 'full_width_components_3_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(28851, 795, '_full_width_components_3_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(28852, 795, 'full_width_components_3_alternating_image_text_1_image', '335'),
(28853, 795, '_full_width_components_3_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(28854, 795, 'full_width_components_3_alternating_image_text_2_title', 'Our Training Credentials'),
(28855, 795, '_full_width_components_3_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(28856, 795, 'full_width_components_3_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(28857, 795, '_full_width_components_3_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(28858, 795, 'full_width_components_3_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
