(29044, 796, 'full_width_components_3_component_title', 'What makes us different'),
(29045, 796, '_full_width_components_3_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(29046, 796, 'full_width_components_3_alternating_image_text_0_title', 'Our Team'),
(29047, 796, '_full_width_components_3_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(29048, 796, 'full_width_components_3_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(29049, 796, '_full_width_components_3_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(29050, 796, 'full_width_components_3_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(29051, 796, '_full_width_components_3_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(29052, 796, 'full_width_components_3_alternating_image_text_0_image', '334'),
(29053, 796, '_full_width_components_3_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(29054, 796, 'full_width_components_3_alternating_image_text_1_title', 'Our Philosophy'),
(29055, 796, '_full_width_components_3_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(29056, 796, 'full_width_components_3_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(29057, 796, '_full_width_components_3_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(29058, 796, 'full_width_components_3_alternating_image_text_1_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
(29059, 796, '_full_width_components_3_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(29060, 796, 'full_width_components_3_alternating_image_text_1_image', '335'),
(29061, 796, '_full_width_components_3_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(29062, 796, 'full_width_components_3_alternating_image_text_2_title', 'Our Training Credentials'),
(29063, 796, '_full_width_components_3_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(29064, 796, 'full_width_components_3_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(29065, 796, '_full_width_components_3_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(29066, 796, 'full_width_components_3_alternating_image_text_2_read_more_link', 'a:3:{s:5:\"title\";s:20:\"Consultancy Services\";s:3:\"url\";s:51:\"https://cognitas.msonet.co.uk/consultancy-services/\";s:6:\"target\";s:0:\"\";}'),
