(29079, 796, '_full_width_components_5_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(29080, 796, 'full_width_components_5_two_column_content_0_column_style', 'image-right'),
(29081, 796, '_full_width_components_5_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(29082, 796, 'full_width_components_5_two_column_content_0_title', ''),
(29083, 796, '_full_width_components_5_two_column_content_0_title', 'field_5ed8f3421c210'),
(29084, 796, 'full_width_components_5_two_column_content_0_text', 'Skills for Justice (SFJ) Awards is an awarding organisation approved by the Qualification Regulators to provide qualifications in England, Wales and Northern Ireland. We were awarded SFJ Centre Approval Status in November 2019 this allows our company to design and deliver accredited training globally under their Accredited Learning professionally (ALP) scheme.\r\n\r\nBy working with SFJ Awards, we can develop and implement accredited and certificated learning programmes that adhere to a recognised quality assurance process.\r\n\r\nThis results in a quality, collaborative, tailored training programme which allows our clients to have confidence in the learning product they create with us. It also ensures learners have the appropriate skills to do their jobs with proficiency.'),
(29085, 796, '_full_width_components_5_two_column_content_0_text', 'field_5ed8f3421c225'),
(29086, 796, 'full_width_components_5_two_column_content_0_read_more_link', ''),
