(29092, 796, 'full_width_components_6_text', 'Working with the community'),
(29093, 796, '_full_width_components_6_text', 'field_5eabd11823e61_field_5eabd07d0cb5b'),
(29094, 796, 'full_width_components_6_text_position', 'center'),
