(29199, 7, '_full_width_components_3_team_members_row', 'field_5eda47d03c7cb_field_5ef48f1d04ed4'),
(29200, 7, 'full_width_components_4_component_title', 'What makes us different'),
(29201, 7, '_full_width_components_4_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(29202, 7, 'full_width_components_4_alternating_image_text_0_title', 'Our Team'),
(29203, 7, '_full_width_components_4_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(29204, 7, 'full_width_components_4_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(29205, 7, '_full_width_components_4_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(29206, 7, 'full_width_components_4_alternating_image_text_0_read_more_link', ''),
(29207, 7, '_full_width_components_4_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(29208, 7, 'full_width_components_4_alternating_image_text_0_image', '334'),
(29209, 7, '_full_width_components_4_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(29210, 7, 'full_width_components_4_alternating_image_text_1_title', 'Our Philosophy'),
(29211, 7, '_full_width_components_4_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(29212, 7, 'full_width_components_4_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(29213, 7, '_full_width_components_4_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(29214, 7, 'full_width_components_4_alternating_image_text_1_read_more_link', ''),
(29215, 7, '_full_width_components_4_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(29216, 7, 'full_width_components_4_alternating_image_text_1_image', '335'),
(29217, 7, '_full_width_components_4_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(29218, 7, 'full_width_components_4_alternating_image_text_2_title', 'Our Training Credentials'),
(29219, 7, '_full_width_components_4_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(29220, 7, 'full_width_components_4_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(29221, 7, '_full_width_components_4_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(29222, 7, 'full_width_components_4_alternating_image_text_2_read_more_link', ''),
