(29409, 800, '_full_width_components_3_team_members_row', 'field_5eda47d03c7cb_field_5ef48f1d04ed4'),
(29410, 800, 'full_width_components_4_component_title', 'What makes us different'),
(29411, 800, '_full_width_components_4_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(29412, 800, 'full_width_components_4_alternating_image_text_0_title', 'Our Team'),
(29413, 800, '_full_width_components_4_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(29414, 800, 'full_width_components_4_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(29415, 800, '_full_width_components_4_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(29416, 800, 'full_width_components_4_alternating_image_text_0_read_more_link', 'a:3:{s:5:\"title\";s:8:\"About Us\";s:3:\"url\";s:39:\"https://cognitas.msonet.co.uk/about-us/\";s:6:\"target\";s:0:\"\";}'),
(29417, 800, '_full_width_components_4_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(29418, 800, 'full_width_components_4_alternating_image_text_0_image', '334'),
(29419, 800, '_full_width_components_4_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(29420, 800, 'full_width_components_4_alternating_image_text_1_title', 'Our Philosophy'),
(29421, 800, '_full_width_components_4_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(29422, 800, 'full_width_components_4_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.');
