(29428, 800, 'full_width_components_4_alternating_image_text_2_title', 'Our Training Credentials'),
(29429, 800, '_full_width_components_4_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(29430, 800, 'full_width_components_4_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
