(29698, 803, 'full_width_components_4_alternating_image_text_1_image', '335'),
(29699, 803, '_full_width_components_4_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(29700, 803, 'full_width_components_4_alternating_image_text_2_title', 'Our Training Credentials'),
(29701, 803, '_full_width_components_4_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(29702, 803, 'full_width_components_4_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(29703, 803, '_full_width_components_4_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
