(29744, 803, 'full_width_components_10_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(29745, 803, '_full_width_components_10_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(29746, 803, 'full_width_components_10_component_subtitle', ''),
(29747, 803, '_full_width_components_10_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(29748, 803, 'full_width_components_10_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(29749, 803, '_full_width_components_10_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
