(29890, 806, 'full_width_components_6_reduce_image_sizes', 'larger-images'),
(29891, 806, '_full_width_components_6_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(29892, 806, 'full_width_components_6_two_column_content_0_column_style', 'image-right'),
(29893, 806, '_full_width_components_6_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(29894, 806, 'full_width_components_6_two_column_content_0_title', ''),
(29895, 806, '_full_width_components_6_two_column_content_0_title', 'field_5ed8f3421c210'),
(29896, 806, 'full_width_components_6_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(29897, 806, '_full_width_components_6_two_column_content_0_text', 'field_5ed8f3421c225'),
(29898, 806, 'full_width_components_6_two_column_content_0_read_more_link', ''),
