(30262, 809, 'full_width_components_3_team_members_row', '1'),
(30263, 809, '_full_width_components_3_team_members_row', 'field_5eda47d03c7cb_field_5ef48f1d04ed4'),
(30264, 809, 'full_width_components_4_component_title', 'What makes us different'),
(30265, 809, '_full_width_components_4_component_title', 'field_5eac01fd2e75f_field_5eac06d8f0ba3'),
(30266, 809, 'full_width_components_4_alternating_image_text_0_title', 'Our Team'),
(30267, 809, '_full_width_components_4_alternating_image_text_0_title', 'field_5eac06415f1f1'),
(30268, 809, 'full_width_components_4_alternating_image_text_0_text', 'At Cognitas, every member of our highly qualified and motivated team is a specialist in their field. Together, we bring extensive learning and development experience, complimented by many years of operational expertise. This enables us to deliver technical support and training within all areas of the public and private sectors '),
(30269, 809, '_full_width_components_4_alternating_image_text_0_text', 'field_5eac064a5f1f2'),
(30270, 809, 'full_width_components_4_alternating_image_text_0_read_more_link', ''),
(30271, 809, '_full_width_components_4_alternating_image_text_0_read_more_link', 'field_5eac06535f1f3'),
(30272, 809, 'full_width_components_4_alternating_image_text_0_image', '334'),
(30273, 809, '_full_width_components_4_alternating_image_text_0_image', 'field_5e70f0ef0dfd6'),
(30274, 809, 'full_width_components_4_alternating_image_text_1_title', 'Our Philosophy'),
(30275, 809, '_full_width_components_4_alternating_image_text_1_title', 'field_5eac06415f1f1'),
(30276, 809, 'full_width_components_4_alternating_image_text_1_text', 'We provide engaging, cost-effective learning solutions, with the necessary commercial acumen to ensure they’re sustainable too. But what sets us apart from other training companies is our commitment to transparency and the strong moral and ethical values, nurtured from our work in countries emerging from corruption, conflict and pollical transition.'),
(30277, 809, '_full_width_components_4_alternating_image_text_1_text', 'field_5eac064a5f1f2'),
(30278, 809, 'full_width_components_4_alternating_image_text_1_read_more_link', ''),
(30279, 809, '_full_width_components_4_alternating_image_text_1_read_more_link', 'field_5eac06535f1f3'),
(30280, 809, 'full_width_components_4_alternating_image_text_1_image', '335'),
(30281, 809, '_full_width_components_4_alternating_image_text_1_image', 'field_5e70f0ef0dfd6'),
(30282, 809, 'full_width_components_4_alternating_image_text_2_title', 'Our Training Credentials'),
(30283, 809, '_full_width_components_4_alternating_image_text_2_title', 'field_5eac06415f1f1'),
(30284, 809, 'full_width_components_4_alternating_image_text_2_text', 'Underpinning our work is the belief that a company that offers needs analysis and the design and delivery of training solutions should have formal Learning and Development qualifications. <br><br>  We are a Skills for Justice Awards Approved Training Centre and have provided accredited training for international government organisations across the globe – always with the same rigorous academic and learning design standards.<br><br>'),
(30285, 809, '_full_width_components_4_alternating_image_text_2_text', 'field_5eac064a5f1f2'),
(30286, 809, 'full_width_components_4_alternating_image_text_2_read_more_link', ''),
