(30325, 809, '_full_width_components_9_background_image', 'field_5eabd11823e61_field_5eabd06d0cb5a'),
(30326, 809, 'full_width_components_10_component_title', 'We recognise a moral responsibility to extend our knowledge and expertise out into the community, specifically to enterprises which support the young, vulnerable, or those requiring full-time care'),
(30327, 809, '_full_width_components_10_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(30328, 809, 'full_width_components_10_component_subtitle', ''),
(30329, 809, '_full_width_components_10_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(30330, 809, 'full_width_components_10_content', 'Cognitas Global is currently working with a small number of UK-based educational and charitable organisations who need assistance with their Learning and Development programmes and may not be able to finance that themselves.\r\n\r\nWe are now taking applications for 2021.'),
(30331, 809, '_full_width_components_10_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
