(31073, 823, '_full_width_components_1_title', 'field_5eaaa9e6b2cfb_field_5eaaa8a084c50'),
(31074, 823, 'full_width_components_1_subtitle', 'If you need to test and develop decision making skills, our versatile View360 Global™ platform allows you to create an immersive online learning environment tailored to meet your specific needs.  <br><br> Here are just some of the areas where our clients have discovered its advantages:'),
(31075, 823, '_full_width_components_1_subtitle', 'field_5eaaa9e6b2cfb_field_5eaaa8ad84c51'),
(31076, 823, 'full_width_components_1_left_side_bullet_points_0_bullet_point', 'Crisis management response'),
