(31500, 824, 'full_width_components_7_reduce_image_sizes', 'larger-images'),
(31501, 824, '_full_width_components_7_reduce_image_sizes', 'field_5ed8f49bb1b3b_field_5ee9fa2342cb6'),
(31502, 824, 'full_width_components_7_two_column_content_0_column_style', 'image-right'),
(31503, 824, '_full_width_components_7_two_column_content_0_column_style', 'field_5ed8f395410e1'),
(31504, 824, 'full_width_components_7_two_column_content_0_title', ''),
(31505, 824, '_full_width_components_7_two_column_content_0_title', 'field_5ed8f3421c210'),
(31506, 824, 'full_width_components_7_two_column_content_0_text', 'Whether you opt for View360 Global™ licencing plan or choose to work with us on a consultancy basis, we provide comprehensive support.\r\n\r\nAll our clients receive dedicated training on the technical use of the platform, as well as course design and delivery methodologies at no extra cost.\r\n\r\nOur Account Management System, accessible through our website provides clients with the ability to monitor usage, customise users, obtain technical assistance and access online tutorials.'),
(31507, 824, '_full_width_components_7_two_column_content_0_text', 'field_5ed8f3421c225'),
(31508, 824, 'full_width_components_7_two_column_content_0_read_more_link', ''),
