(31522, 426, 'full_width_components_0_circular_infographic_items_0_circular_infographic_content', 'User FriendlyINSERT INTO `wpcu_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(31795, 827, '_components_0_timeline_items', 'field_5ebd0548c3669_field_5ebd0228d7bfc'),
(31796, 827, 'full_width_components_0_component_title', 'The Benefits of Bringing Immersive Learning To Your Organisation'),
(31797, 827, '_full_width_components_0_component_title', 'field_5eabf9d6ed25f_field_5eabf7d5b9db7'),
(31798, 827, 'full_width_components_0_component_subtitle', 'Immersive learning takes real situations and allows the learner to control the outcome; connecting with realistic experiences in a safe environment. By allowing room for mistakes, the learner can practice making decisions and understand the effects before applying them to real life.'),
(31799, 827, '_full_width_components_0_component_subtitle', 'field_5eabf9d6ed25f_field_5eabf7d5b9dce'),
(31800, 827, 'full_width_components_0_content', '&nbsp;\r\n<h4>View360 Global™ promotes these principles in the delivery process</h4>\r\n<img class=\"alignnone wp-image-826 size-full\" src=\"https://cognitas.msonet.co.uk/wp-content/uploads/2020/06/Immersive-process-1.png\" alt=\"\" width=\"6668\" height=\"2361\" />\r\n\r\nView360 Global™ has been used by clients and practitioners in many countries throughout Europe, Asia and the Caribbean'),
(31801, 827, '_full_width_components_0_content', 'field_5eabf9d6ed25f_field_5eabf802e27a5'),
(31802, 827, 'full_width_components_0_buttons', ''),
