(31831, 827, '_full_width_components_1_gallery_items', 'field_5ed763b6b1690_field_5d8dbaaa76571'),
(31832, 827, 'full_width_components_2_content', '<blockquote>\r\n<p style=\"text-align: center;\">“Knowledge results from the combination of grasping experience and transforming it.”\r\n- <i>Professor D.A Kolb - Kolb’s theory of experiential learning</i></p>\r\n</blockquote>\r\n<p style=\"text-align: center;\">Find out more about immersive training and how <b>View360 Global™</b> can help you transform your business</p>'),
(31833, 827, '_full_width_components_2_content', 'field_5e3bd2cd0eec0_field_5953822b26d50'),
(31834, 827, 'full_width_components_3_buttons_0_button', 'a:3:{s:5:\"title\";s:10:\"Contact Us\";s:3:\"url\";s:38:\"https://cognitas.msonet.co.uk/contact/\";s:6:\"target\";s:0:\"\";}'),
(31835, 827, '_full_width_components_3_buttons_0_button', 'field_5ed90856b39bb'),
(31836, 827, 'full_width_components_3_buttons', '1'),
(31837, 827, '_full_width_components_3_buttons', 'field_5ed90879348a4_field_5ed90856ad1ce'),
(31838, 827, 'full_width_components_4_component_title', 'Immersive media - bringing creativity to life'),
(31839, 827, '_full_width_components_4_component_title', 'field_5ed7633432b54_field_5ea9847fcbc59'),
(31840, 827, 'full_width_components_4_component_subtitle', 'Immersion refers to the mental state of being completely absorbed or engaged with an activity. It is a powerful vehicle for identity and knowledge transfer, both of which are crucial factors affecting learning outcomes. '),
(31841, 827, '_full_width_components_4_component_subtitle', 'field_5ed7633432b54_field_5ea98490cbc5a'),
(31842, 827, 'full_width_components_4_icons_0_icon', '812'),
(31843, 827, '_full_width_components_4_icons_0_icon', 'field_5ea984ddcbc5d'),
(31844, 827, 'full_width_components_4_icons_0_text', 'The quality of the mixed media will determine the level of immersion '),
(31845, 827, '_full_width_components_4_icons_0_text', 'field_5ea984e6cbc5e'),
(31846, 827, 'full_width_components_4_icons', '1'),
(31847, 827, '_full_width_components_4_icons', 'field_5ed7633432b54_field_5ea9849acbc5b'),
(31848, 827, 'full_width_components_4_component_bottom_content', 'Our Design Team can produce bespoke digital content and immersive media (IM) for our clients and practitioners to ensure that by blending real world with authentic digital content, learners experience true reality.\r\n\r\nUsing the latest design software programs we will create IM such as video, documents, photographs and audio to ensure that the learning is truly enhanced by providing the information and knowledge in a real and stimulating way.\r\n\r\n&nbsp;'),
(31849, 827, '_full_width_components_4_component_bottom_content', 'field_5ed7633432b54_field_5ea984a5cbc5c'),
